        public static readonly ElementDef[] All =
        {
            new ElementDef { Number = 1, Symbol = "H", NameZh = "氢", NameEn = "Hydrogen", Category = "nonmetal", Mass = 1.008, Value = 3, Group = 1, Period = 1, Phase = "Gas", Block = "s", ElectronConfig = "1s1", DensityUnit = "g/L", DiscoveredBy = "Henry Cavendish", NamedBy = "Antoine Lavoisier", SummaryZh = "宇宙里存货最多的元素，恒星靠它聚变成光，地球上主要以水的形式存在。工业上拿它合成氨、给油品加氢，低温下压成液氢还能当火箭燃料，当铺里按纯度论价。谁家合成台点不着火，先查它的气瓶。", SummaryEn = "The most abundant element in the universe, burning in stars and locked up in water on Earth. Industry turns it into ammonia and hydrogenates fuel, and liquid hydrogen still makes a premium rocket propellant. When a synthesis bench refuses to light, check its gas cylinder first.", MeltC = -259.2, BoilC = -252.9, Density = 0.09, Electronegativity = 2.2 },
            new ElementDef { Number = 2, Symbol = "He", NameZh = "氦", NameEn = "Helium", Category = "noble_gas", Mass = 4.0026, Value = 55, Group = 18, Period = 1, Phase = "Gas", Block = "s", ElectronConfig = "1s2", DensityUnit = "g/L", DiscoveredBy = "Pierre Janssen", NamedBy = "", SummaryZh = "宇宙中第二多的元素，地球上只能从天然气田里一点点提出来，用完就没了。液氦是超导磁体和核磁共振机的冷却液，轻飘飘又惰性，是废土里最稳的保冷货。瓶子一开就往上飘，跑得比谁都快。", SummaryEn = "Second only to hydrogen in cosmic abundance, captured in small amounts from natural gas and gone once used. Liquid helium chills superconducting magnets and MRI machines, and its inertia makes it a safe cold-storage good in the wasteland. Open a bottle and it bolts upward faster than anything.", MeltC = -272.2, BoilC = -268.9, Density = 0.179 },
            new ElementDef { Number = 3, Symbol = "Li", NameZh = "锂", NameEn = "Lithium", Category = "alkali_metal", Mass = 6.94, Value = 20, Group = 1, Period = 2, Phase = "Solid", Block = "s", ElectronConfig = "[He] 2s1", DensityUnit = "g/cm3", DiscoveredBy = "Johan August Arfwedson", NamedBy = "", SummaryZh = "最轻的金属，密度小到能浮在水面和煤油上，遇水还会冒氢气。锂离子电池、手机、电动车都靠它续命，早年还当过治躁郁症的药，当铺收它先看是不是电池级。旧电池堆成山的角落，就是废土上最像矿脉的地方。", SummaryEn = "The lightest metal, buoyant enough to float on water and oil, and it fizzes off hydrogen when wet. Lithium-ion cells keep phones and EVs alive, and it once served as a mood-stabilizing medicine, so buyers check for battery grade. Where dead batteries pile into hills, the wasteland has its closest thing to a mine.", MeltC = 180.5, BoilC = 1329.8, Density = 0.534, Electronegativity = 0.98 },
            new ElementDef { Number = 4, Symbol = "Be", NameZh = "铍", NameEn = "Beryllium", Category = "alkaline_earth", Mass = 9.0122, Value = 32, Group = 2, Period = 2, Phase = "Solid", Block = "s", ElectronConfig = "[He] 2s2", DensityUnit = "g/cm3", DiscoveredBy = "Louis Nicolas Vauquelin", NamedBy = "", SummaryZh = "又轻又硬的银灰金属，对 X 射线几乎透明，用来做 X 光管窗口；粉尘有剧毒，吸入会得慢性肺病。航天和核反应堆里当结构件，验货得戴好滤罐。它轻得反常，硬得也反常，别徒手去掰。", SummaryEn = "A pale, light and stiff metal almost transparent to X-rays, used for tube windows, but its dust causes chronic lung disease. Aerospace frames and reactor parts want it, so open the crate with a respirator on. Abnormally light and abnormally stiff, never snap it bare-handed.", MeltC = 1286.8, BoilC = 2468.8, Density = 1.85, Electronegativity = 1.57 },
            new ElementDef { Number = 5, Symbol = "B", NameZh = "硼", NameEn = "Boron", Category = "metalloid", Mass = 10.81, Value = 18, Group = 13, Period = 2, Phase = "Solid", Block = "p", ElectronConfig = "[He] 2s2 2p1", DensityUnit = "g/cm3", DiscoveredBy = "Joseph Louis Gay-Lussac", NamedBy = "", SummaryZh = "硼砂、硼硅玻璃和陶瓷的老原料，也是核反应堆控制棒里的中子吸收剂。植物离不开它，可人吃多了会中毒，粉末状的高纯硼在合成台上抢手。焊工和陶匠的配方里都要丢一小撮，成品才不发脆。", SummaryEn = "The old feedstock for borax, borosilicate glass and ceramics, and a neutron absorber in reactor control rods. Plants need it to grow while people who ingest too much are poisoned; high-purity boron powder is always wanted at the synthesis bench. Welders and potters both toss in a pinch so the finished work does not turn brittle.", MeltC = 2075.8, BoilC = 3926.8, Density = 2.08, Electronegativity = 2.04 },
            new ElementDef { Number = 6, Symbol = "C", NameZh = "碳", NameEn = "Carbon", Category = "nonmetal", Mass = 12.011, Value = 5, Group = 14, Period = 2, Phase = "Solid", Block = "p", ElectronConfig = "[He] 2s2 2p2", DensityUnit = "g/cm3", DiscoveredBy = "", NamedBy = "", SummaryZh = "同一种元素能长成金刚石、石墨、石墨烯和煤炭，是地球上一切有机生命的骨架。炼钢、电极、宝石和碳十四测年都靠它，当铺里真假碳货差价极大。废土上烧一炉好炭，也是门垄断生意。", SummaryEn = "One element that grows into diamond, graphite, graphene and coal, and the backbone of all organic life on Earth. Steelmaking, electrodes, gems and radiocarbon dating all run on it, and the price gap between real and fake carbon is huge. Even burning a good batch of charcoal is a monopoly business in the wasteland.", MeltC = 4326.9, Density = 1.82, Electronegativity = 2.55 },
            new ElementDef { Number = 7, Symbol = "N", NameZh = "氮", NameEn = "Nitrogen", Category = "nonmetal", Mass = 14.007, Value = 6, Group = 15, Period = 2, Phase = "Gas", Block = "p", ElectronConfig = "[He] 2s2 2p3", DensityUnit = "g/L", DiscoveredBy = "Daniel Rutherford", NamedBy = "Jean-Antoine Chaptal", SummaryZh = "空气里占大头的气体，化学上很懒，却是化肥和炸药的源头。液氮拿来冷冻、给食品保鲜，高压瓶装的氮气在废土上是抢手的惰性保护气。轮胎和食品袋里充它防氧化，可密闭舱漏气会让人无声窒息。", SummaryEn = "The bulk of the air we breathe, chemically lazy, yet the root of both fertilizer and explosives. Liquid nitrogen freezes and preserves food, and a pressurized cylinder of inert nitrogen is a hot item in the wasteland. Tires and food bags are filled with it against oxidation, yet a leak in a sealed cabin kills silently.", MeltC = -210.0, BoilC = -195.8, Density = 1.25, Electronegativity = 3.04 },
            new ElementDef { Number = 8, Symbol = "O", NameZh = "氧", NameEn = "Oxygen", Category = "nonmetal", Mass = 15.999, Value = 4, Group = 16, Period = 2, Phase = "Gas", Block = "p", ElectronConfig = "[He] 2s2 2p4", DensityUnit = "g/L", DiscoveredBy = "Carl Wilhelm Scheele", NamedBy = "Antoine Lavoisier", SummaryZh = "空气里第二多的成分，呼吸、燃烧和生锈都离不开它。炼钢吹氧、医疗供氧、火箭氧化剂都是大生意，但纯氧助燃，沾上油污就是事故。高空那层臭氧同样是它，替废土挡住致命的紫外线。", SummaryEn = "The second most common gas in the air, and nothing breathes, burns or rusts without it. Steel mills blow it into furnaces, hospitals sell it by the tank, rockets use it as an oxidizer, and pure oxygen plus oil is an accident waiting to happen. The ozone layer high above is the same element, screening the wasteland from lethal ultraviolet.", MeltC = -218.8, BoilC = -183.0, Density = 1.43, Electronegativity = 3.44 },
            new ElementDef { Number = 9, Symbol = "F", NameZh = "氟", NameEn = "Fluorine", Category = "halogen", Mass = 18.998, Value = 8, Group = 17, Period = 2, Phase = "Gas", Block = "p", ElectronConfig = "[He] 2s2 2p5", DensityUnit = "g/L", DiscoveredBy = "André-Marie Ampère", NamedBy = "Humphry Davy", SummaryZh = "最活泼的非金属，几乎能和所有元素反应，连玻璃都能腐蚀。萤石里提取，用来做特氟龙、含氟牙膏，还用于铀浓缩；单质和氢氟酸都是要命的毒货。存它得用特制容器，普通玻璃瓶撑不过一夜。", SummaryEn = "The most reactive nonmetal, attacking nearly every element and even etching glass. Extracted from fluorite for Teflon, fluoride toothpaste and uranium enrichment, while the element and hydrofluoric acid are lethal goods. It needs special containers; an ordinary glass bottle will not survive the night.", MeltC = -219.7, BoilC = -188.1, Density = 1.7, Electronegativity = 3.98 },
            new ElementDef { Number = 10, Symbol = "Ne", NameZh = "氖", NameEn = "Neon", Category = "noble_gas", Mass = 20.18, Value = 45, Group = 18, Period = 2, Phase = "Gas", Block = "p", ElectronConfig = "[He] 2s2 2p6", DensityUnit = "g/L", DiscoveredBy = "Morris Travers", NamedBy = "", SummaryZh = "从液态空气里分出来的惰性气体，通电就发橙红色光，霓虹灯因此得名。化学上几乎不反应，除了招牌和激光，当铺里就是一小瓶好看的废土纪念品。它在低温实验里当过冷却介质，量少得靠整瓶空气去换。", SummaryEn = "An inert gas distilled from liquid air that glows orange-red when electrified, which is how neon signs got their name. It barely reacts with anything, so beyond signs and lasers it is just a pretty little bottle of wasteland souvenir. It has served as a cryogenic medium, so little that whole air bottles are traded for it.", MeltC = -248.6, BoilC = -246.0, Density = 0.9 },
            new ElementDef { Number = 11, Symbol = "Na", NameZh = "钠", NameEn = "Sodium", Category = "alkali_metal", Mass = 22.99, Value = 7, Group = 1, Period = 3, Phase = "Solid", Block = "s", ElectronConfig = "[Ne] 3s1", DensityUnit = "g/cm3", DiscoveredBy = "Humphry Davy", NamedBy = "", SummaryZh = "食盐里的金属，软得能用刀切，遇水剧烈反应甚至着火。电解熔盐制钠，钠灯、核反应堆冷却剂和肥皂工业都要它，废土厨房里它是最便宜的硬通货。它遇水还会放出氢气，旧仓库里堆钠等于埋了颗雷。", SummaryEn = "The metal inside table salt, soft enough to cut with a knife and violent when it meets water. Electrolysis of molten salt produces it for sodium lamps, reactor coolant and soap, and in a wasteland kitchen salt is still the cheapest hard currency. It also gives off hydrogen when wet, so a sodium stockpile in an old warehouse is a buried bomb.", MeltC = 97.8, BoilC = 882.9, Density = 0.968, Electronegativity = 0.93 },
            new ElementDef { Number = 12, Symbol = "Mg", NameZh = "镁", NameEn = "Magnesium", Category = "alkaline_earth", Mass = 24.305, Value = 10, Group = 2, Period = 3, Phase = "Solid", Block = "s", ElectronConfig = "[Ne] 3s2", DensityUnit = "g/cm3", DiscoveredBy = "Joseph Black", NamedBy = "", SummaryZh = "轻得像塑料的银白金属，烧起来发出刺眼白光，早年用来做闪光粉和燃烧弹。叶绿素的核心就是镁，合金用于汽车和相机机身，粉末要防潮防火。补剂里也有它，缺了容易抽筋和心慌，药房常备。", SummaryEn = "A silver-white metal light as plastic that burns with a blinding white flame, once used in flash powder and incendiaries. Chlorophyll runs on a magnesium core, alloys go into cars and camera bodies, and the powder must be kept dry and fireproof. Supplements carry it too, and a shortage brings cramps and palpitations, so pharmacies keep it.", MeltC = 649.9, BoilC = 1089.8, Density = 1.74, Electronegativity = 1.31 },
            new ElementDef { Number = 13, Symbol = "Al", NameZh = "铝", NameEn = "Aluminum", Category = "post_transition", Mass = 26.982, Value = 11, Group = 13, Period = 3, Phase = "Solid", Block = "p", ElectronConfig = "[Ne] 3s2 3p1", DensityUnit = "g/cm3", DiscoveredBy = "", NamedBy = "Humphry Davy", SummaryZh = "地壳里最多的金属，表面会自己生成氧化膜所以耐腐蚀，可电解炼铝极耗电。飞机、易拉罐、箔纸和电线处处是它，一百多年前还算贵金属，当铺里按合金牌号收。废土上最不缺的就是废铝，压成锭再卖才值钱。", SummaryEn = "The most abundant metal in the crust, self-protecting with an oxide skin, yet smelting it by electrolysis eats enormous power. Planes, cans, foil and cables are all aluminum, and a century ago it counted as a precious metal, so buyers price it by alloy grade. Scrap aluminum is the wasteland's least scarce thing; press it into ingots before selling.", MeltC = 660.3, BoilC = 2469.8, Density = 2.7, Electronegativity = 1.61 },
            new ElementDef { Number = 14, Symbol = "Si", NameZh = "硅", NameEn = "Silicon", Category = "metalloid", Mass = 28.085, Value = 8, Group = 14, Period = 3, Phase = "Solid", Block = "p", ElectronConfig = "[Ne] 3s2 3p2", DensityUnit = "g/cm3", DiscoveredBy = "Jöns Jacob Berzelius", NamedBy = "Thomas Thomson (chemist)", SummaryZh = "沙子、石英和玻璃的主心骨，芯片和太阳能板全靠高纯硅。它是半导体工业的粮食，也撑起硅胶和水泥，当铺收硅片先看晶圆有没有裂。旧芯片和碎玻璃都有人收，走一趟熔炉就是一份口粮。", SummaryEn = "The backbone of sand, quartz and glass, and the feedstock for chips and solar panels. It is the staple of the semiconductor trade and also props up silicone and cement, so a buyer checks wafers for cracks first. Dead chips and broken glass both find buyers, and one trip to the furnace buys a meal.", MeltC = 1413.8, BoilC = 3264.8, Density = 2.33, Electronegativity = 1.9 },
            new ElementDef { Number = 15, Symbol = "P", NameZh = "磷", NameEn = "Phosphorus", Category = "nonmetal", Mass = 30.974, Value = 9, Group = 15, Period = 3, Phase = "Solid", Block = "p", ElectronConfig = "[Ne] 3s2 3p3", DensityUnit = "g/cm3", DiscoveredBy = "Hennig Brand", NamedBy = "", SummaryZh = "白磷在空气里会自燃发光，因此得名，红磷则拿来做火柴和阻燃剂。磷是 DNA、骨骼和化肥的必需元素，但白磷有剧毒，接触皮肤会深度烧伤。废土上没人敢徒手碰白磷，手上的温度就够把它点着。", SummaryEn = "White phosphorus glows in air and burns on its own, which is how it got its name, while the red form goes into matches and flame retardants. Phosphorus is essential to DNA, bone and fertilizer, but white phosphorus is viciously toxic and burns deep into skin. No one in the wasteland handles white phosphorus bare-handed; body heat alone can set it alight.", MeltC = 44.2, Density = 1.82, Electronegativity = 2.19 },
            new ElementDef { Number = 16, Symbol = "S", NameZh = "硫", NameEn = "Sulfur", Category = "nonmetal", Mass = 32.06, Value = 8, Group = 16, Period = 3, Phase = "Solid", Block = "p", ElectronConfig = "[Ne] 3s2 3p4", DensityUnit = "g/cm3", DiscoveredBy = "", NamedBy = "", SummaryZh = "火山口和温泉边常见的黄色晶体，古称硫磺。硫酸是化工之母，橡胶硫化、火药和化肥都离不开它，燃烧时的臭鸡蛋味是废土上最好认的路标。硫磺皂和药膏里也有它，便宜得很，却治得了不少皮毛病。", SummaryEn = "Yellow crystals common around volcanoes and hot springs, known since antiquity as brimstone. Sulfuric acid is the mother of the chemical industry, and vulcanized rubber, gunpowder and fertilizer all need it; the rotten-egg stench is the wasteland's easiest landmark. Sulfur soap and ointment carry it as well, dirt cheap and good for a surprising number of skin troubles.", MeltC = 115.2, BoilC = 444.6, Density = 2.07, Electronegativity = 2.58 },
            new ElementDef { Number = 17, Symbol = "Cl", NameZh = "氯", NameEn = "Chlorine", Category = "halogen", Mass = 35.45, Value = 7, Group = 17, Period = 3, Phase = "Gas", Block = "p", ElectronConfig = "[Ne] 3s2 3p5", DensityUnit = "g/L", DiscoveredBy = "Carl Wilhelm Scheele", NamedBy = "", SummaryZh = "黄绿色有毒气体，名字本意就是黄绿，第一次世界大战时被当毒气用。如今主要用来消毒水、做漂白剂和聚氯乙烯，食盐里也有它，危险品柜常客。泳池和饮用水靠它消毒，剂量差一点就是另一回事。", SummaryEn = "A yellow-green toxic gas whose name literally means yellow-green, and a chemical weapon in the First World War. Today it disinfects water, bleaches and makes PVC, and it still sits in table salt, so it lives in the hazardous cabinet. Pools and drinking water are disinfected by it, and a slight dose change makes it another matter entirely.", MeltC = -101.5, BoilC = -34.0, Density = 3.2, Electronegativity = 3.16 },
            new ElementDef { Number = 18, Symbol = "Ar", NameZh = "氩", NameEn = "Argon", Category = "noble_gas", Mass = 39.948, Value = 40, Group = 18, Period = 3, Phase = "Gas", Block = "p", ElectronConfig = "[Ne] 3s2 3p6", DensityUnit = "g/L", DiscoveredBy = "Lord Rayleigh", NamedBy = "", SummaryZh = "空气里最多的稀有气体，含量比二氧化碳还高，化学上几乎完全惰性。焊接时当保护气、灯泡里当填充气，名字本意是懒惰，废土上算最省心的气体。密封舱里充它防火防锈，惰性得让人忘了它还在。", SummaryEn = "The most plentiful noble gas in the air, more common than carbon dioxide and almost totally inert. Welders use it as a shield and bulbs use it as filler, and its name means lazy, making it the most low-maintenance gas in the wasteland. Sealed cabins fill with it against fire and rust, so inert that people forget it is there.", MeltC = -189.3, BoilC = -185.8, Density = 1.78 },
            new ElementDef { Number = 19, Symbol = "K", NameZh = "钾", NameEn = "Potassium", Category = "alkali_metal", Mass = 39.098, Value = 15, Group = 1, Period = 4, Phase = "Solid", Block = "s", ElectronConfig = "[Ar] 4s1", DensityUnit = "g/cm3", DiscoveredBy = "Humphry Davy", NamedBy = "", SummaryZh = "香蕉、土豆和化肥里都有的活泼金属，遇水会烧起来，钾离子维持神经和心跳。钾盐是农业的硬通货，放射性钾四十还能给地质和年代测定帮忙。血钾失衡能让人心跳乱套，急救箱里得备着它的盐。", SummaryEn = "A lively metal found in bananas, potatoes and potash, burning on contact with water and keeping nerves and heartbeat in rhythm. Potash is a hard agricultural currency, and radioactive potassium forty still helps date rocks. Lopsided blood potassium throws the heartbeat into chaos, so the trauma kit keeps its salts.", MeltC = 63.6, BoilC = 758.9, Density = 0.862, Electronegativity = 0.82 },
            new ElementDef { Number = 20, Symbol = "Ca", NameZh = "钙", NameEn = "Calcium", Category = "alkaline_earth", Mass = 40.078, Value = 9, Group = 2, Period = 4, Phase = "Solid", Block = "s", ElectronConfig = "[Ar] 4s2", DensityUnit = "g/cm3", DiscoveredBy = "Humphry Davy", NamedBy = "", SummaryZh = "骨骼、牙齿、石灰岩和贝壳的主角，石灰石烧成水泥和生石灰全靠它。金属钙是强还原剂，钙片和石膏也常见，遇水放氢气，存放要隔绝潮湿。拆楼的混凝土块和贝壳堆都是它的矿，废土上遍地是原料。", SummaryEn = "The star of bones, teeth, limestone and seashells, and the stuff of cement and quicklime. The metal itself is a strong reducing agent that fizzes hydrogen in water, and calcium tablets and plaster are common goods, so store it dry. Crushed concrete and shell heaps are its ore, and the wasteland is paved with raw material.", MeltC = 841.9, BoilC = 1483.8, Density = 1.55, Electronegativity = 1.0 },
            new ElementDef { Number = 21, Symbol = "Sc", NameZh = "钪", NameEn = "Scandium", Category = "transition_metal", Mass = 44.956, Value = 35, Group = 3, Period = 4, Phase = "Solid", Block = "d", ElectronConfig = "[Ar] 3d1 4s2", DensityUnit = "g/cm3", DiscoveredBy = "Lars Fredrik Nilson", NamedBy = "", SummaryZh = "钪是过渡金属里最轻的一位，名字来自北欧的斯堪的纳维亚。它常被掺进铝里做高档自行车和航天件，也用于高强度灯和激光；矿源稀少，当铺按克收。旧车架和拆下来的航天件里能抠出它，量少得像淘金。", SummaryEn = "The lightest of the transition metals, named after Scandinavia. Blended into aluminum for premium bikes and aerospace parts and used in bright lamps and lasers, it is dispersed and scarce, so the pawnshop pays by the gram. Old frames and stripped aerospace parts give up a little of it, rarefied like gold panning.", MeltC = 1540.8, BoilC = 2835.8, Density = 2.98, Electronegativity = 1.36 },
            new ElementDef { Number = 22, Symbol = "Ti", NameZh = "钛", NameEn = "Titanium", Category = "transition_metal", Mass = 47.867, Value = 30, Group = 4, Period = 4, Phase = "Solid", Block = "d", ElectronConfig = "[Ar] 3d2 4s2", DensityUnit = "g/cm3", DiscoveredBy = "William Gregor", NamedBy = "Martin Heinrich Klaproth", SummaryZh = "比钢轻却同样结实，耐腐蚀又亲生物，人工关节和飞机骨架都爱用它。白色二氧化钛是最常见的颜料，金属钛冶炼困难，所以废土上钛料一直溢价。它在海水里泡不烂，船件和换热器都爱用它。", SummaryEn = "As strong as steel yet far lighter, corrosion-proof and body-friendly, so artificial joints and aircraft frames love it. White titanium dioxide is the most common pigment on Earth, but smelting the metal is hard, which keeps titanium scrap at a premium in the wasteland. It does not rot in seawater, so ship parts and heat exchangers love it.", MeltC = 1667.8, BoilC = 3286.8, Density = 4.51, Electronegativity = 1.54 },
            new ElementDef { Number = 23, Symbol = "V", NameZh = "钒", NameEn = "Vanadium", Category = "transition_metal", Mass = 50.942, Value = 32, Group = 5, Period = 4, Phase = "Solid", Block = "d", ElectronConfig = "[Ar] 3d3 4s2", DensityUnit = "g/cm3", DiscoveredBy = "Andrés Manuel del Río", NamedBy = "Isotopes of vanadium", SummaryZh = "钒加进钢里能显著提高强度和耐磨性，是重轨和工具钢的调味料。钒液流电池用来储电，化合物五颜六色但多有毒性，催化剂里也常见它的身影。化验室里的钒试剂颜色一变，整批货的成色就露馅。", SummaryEn = "A pinch of vanadium makes steel markedly stronger and tougher, the seasoning of rails and tool steel. Vanadium flow batteries store power, its compounds come in vivid colors and many are toxic, and it also turns up in catalysts. A vanadium reagent shifts color in the lab, and the whole batch's grade is exposed.", MeltC = 1909.8, BoilC = 3406.8, Density = 6.0, Electronegativity = 1.63 },
            new ElementDef { Number = 24, Symbol = "Cr", NameZh = "铬", NameEn = "Chromium", Category = "transition_metal", Mass = 51.996, Value = 26, Group = 6, Period = 4, Phase = "Solid", Block = "d", ElectronConfig = "[Ar] 3d5 4s1", DensityUnit = "g/cm3", DiscoveredBy = "Louis Nicolas Vauquelin", NamedBy = "", SummaryZh = "不锈钢之所以不锈，靠的就是铬在表面形成的致密氧化膜。镀铬层亮得能当镜子，红宝石和祖母绿的绿色也来自铬；六价铬有强致癌性，验货要当心。皮革鞣制和金属钝化也要它，量不大却停不了。", SummaryEn = "Stainless steel stays stainless because chromium grows a dense oxide skin on its surface. Chrome plating shines like a mirror, and the red of ruby and green of emerald both come from chromium; hexavalent chromium is a serious carcinogen, so handle it with care. Leather tanning and metal passivation need it too, small in volume but impossible to skip.", MeltC = 1906.8, BoilC = 2670.8, Density = 7.19, Electronegativity = 1.66 },
            new ElementDef { Number = 25, Symbol = "Mn", NameZh = "锰", NameEn = "Manganese", Category = "transition_metal", Mass = 54.938, Value = 24, Group = 7, Period = 4, Phase = "Solid", Block = "d", ElectronConfig = "[Ar] 3d5 4s2", DensityUnit = "g/cm3", DiscoveredBy = "Torbern Olof Bergman", NamedBy = "", SummaryZh = "炼钢时用来脱氧脱硫的黑色金属，钢里加一点就硬得多。干电池正极、高锰酸钾消毒剂和海底锰结核都跟它有关，也是人体必需的微量元素。玻璃匠拿它调色，紫红与深褐都靠它一点点添出来。", SummaryEn = "A black metal used to deoxidize and desulfurize molten steel, and a little of it hardens the batch. Dry-cell cathodes, permanganate disinfectant and seabed nodules all involve manganese, and it is also an essential trace element for the human body. Glassmakers tint with it, coaxing violet-red and deep brown out a little at a time.", MeltC = 1245.8, BoilC = 2060.8, Density = 7.21, Electronegativity = 1.55 },
            new ElementDef { Number = 26, Symbol = "Fe", NameZh = "铁", NameEn = "Iron", Category = "transition_metal", Mass = 55.845, Value = 12, Group = 8, Period = 4, Phase = "Solid", Block = "d", ElectronConfig = "[Ar] 3d6 4s2", DensityUnit = "g/cm3", DiscoveredBy = "", NamedBy = "", SummaryZh = "人类用得最多的金属，地核的主要成分，血红蛋白靠它运送氧气。钢、铸铁和锈迹支撑了整个工业文明，火星的红土也是氧化铁，当铺里铁价最实在。铁锈和泥土里的破伤风菌是老搭档，踩到旧钉子要当心。", SummaryEn = "The most used metal on Earth, the main ingredient of the core, and the atom that carries oxygen in hemoglobin. Steel, cast iron and rust built industrial civilization, and the red soil of Mars is iron oxide, so iron is the honest, steady price in any pawnshop. Rust and the tetanus germ in soil are old partners, so watch for old nails.", MeltC = 1537.8, BoilC = 2860.8, Density = 7.87, Electronegativity = 1.83 },
            new ElementDef { Number = 27, Symbol = "Co", NameZh = "钴", NameEn = "Cobalt", Category = "transition_metal", Mass = 58.933, Value = 35, Group = 9, Period = 4, Phase = "Solid", Block = "d", ElectronConfig = "[Ar] 3d7 4s2", DensityUnit = "g/cm3", DiscoveredBy = "Georg Brandt", NamedBy = "", SummaryZh = "钴蓝颜料自古用来染玻璃和瓷器，如今更是锂电池正极的关键金属。耐高温合金离不开它，人体里少数需要金属的维生素以它为核，粉尘有毒，矿源和价格都很敏感。放射性的钴六十能做辐照灭菌，也能在事故里变成凶器。", SummaryEn = "Cobalt blue has dyed glass and porcelain for centuries, and today it is the critical metal in lithium battery cathodes. Heat-resistant superalloys cannot do without it, a rare human vitamin keeps it at its core, and its dust is toxic with a politically risky supply chain. Radioactive cobalt sixty sterilizes by irradiation and becomes a weapon in accidents.", MeltC = 1494.8, BoilC = 2926.8, Density = 8.9, Electronegativity = 1.88 },
            new ElementDef { Number = 28, Symbol = "Ni", NameZh = "镍", NameEn = "Nickel", Category = "transition_metal", Mass = 58.693, Value = 38, Group = 10, Period = 4, Phase = "Solid", Block = "d", ElectronConfig = "[Ar] 3d8 4s2", DensityUnit = "g/cm3", DiscoveredBy = "Axel Fredrik Cronstedt", NamedBy = "", SummaryZh = "镍让不锈钢更韧、更耐蚀，硬币、电镀层和充电电池里都有它。超合金用于喷气发动机，陨铁里天然含镍；不少人皮肤对其过敏，粉末吸入有致癌风险。废土上收旧币的先测磁性，含镍的才肯给价。", SummaryEn = "Nickel makes stainless steel tougher and more corrosion-resistant, and it appears in coins, plating and rechargeable cells. Superalloys need it for jet engines, iron meteorites carry it naturally, many people are allergic to it and its dust is a cancer risk. Old-coin buyers in the wasteland test magnetism first and only pay for nickel-bearing pieces.", MeltC = 1454.8, BoilC = 2729.8, Density = 8.91, Electronegativity = 1.91 },
            new ElementDef { Number = 29, Symbol = "Cu", NameZh = "铜", NameEn = "Copper", Category = "transition_metal", Mass = 63.546, Value = 22, Group = 11, Period = 4, Phase = "Solid", Block = "d", ElectronConfig = "[Ar] 3d10 4s1", DensityUnit = "g/cm3", DiscoveredBy = "", NamedBy = "", SummaryZh = "人类最早大量使用的金属之一，导电导热极好，青铜时代因它而得名。电线、电机、水管和抗菌表面都靠它，暴露在空气里会慢慢长出绿色铜锈。铸币和首饰里也常见它，成色对了才出高价。", SummaryEn = "One of the first metals people used in bulk, with superb conduction of heat and electricity, and the Bronze Age is named for it. Wiring, motors, pipes and antimicrobial surfaces all rely on copper, and exposed to air it slowly grows a green patina. Coins and jewelry also carry it, and only the right grade earns a high price.", MeltC = 1084.6, BoilC = 2561.8, Density = 8.96, Electronegativity = 1.9 },
            new ElementDef { Number = 30, Symbol = "Zn", NameZh = "锌", NameEn = "Zinc", Category = "transition_metal", Mass = 65.38, Value = 18, Group = 12, Period = 4, Phase = "Solid", Block = "d", ElectronConfig = "[Ar] 3d10 4s2", DensityUnit = "g/cm3", DiscoveredBy = "India", NamedBy = "", SummaryZh = "镀在铁皮上牺牲自己保护钢铁，这就是镀锌的防锈把戏。黄铜、干电池负极、防晒霜和人体免疫都离不开锌，高温下锌蒸气有毒，冶炼要通风。锌片贴船底能防海水咬铁，废土船坞靠它续命。", SummaryEn = "Zinc sacrifices itself on a steel sheet to keep the iron from rusting, the trick behind galvanizing. Brass, battery anodes, sunscreen and human immunity all depend on zinc, and zinc vapor is toxic, so smelters need ventilation. Zinc plates on a hull keep seawater from eating the iron, and wasteland docks live on it.", MeltC = 419.5, BoilC = 906.9, Density = 7.14, Electronegativity = 1.65 },
            new ElementDef { Number = 31, Symbol = "Ga", NameZh = "镓", NameEn = "Gallium", Category = "post_transition", Mass = 69.723, Value = 40, Group = 13, Period = 4, Phase = "Solid", Block = "p", ElectronConfig = "[Ar] 3d10 4s2 4p1", DensityUnit = "g/cm3", DiscoveredBy = "Lecoq de Boisbaudran", NamedBy = "", SummaryZh = "镓的熔点低到能在手心化成液态，却又是做 LED 和砷化镓半导体的好材料。它常伴生在铝土矿里，价格不低；液态镓会腐蚀铝，装它的容器得挑。玻璃厂拿它做低熔点封接，旧仪表铺还留着它的配方。", SummaryEn = "Gallium melts low enough to turn liquid in your palm, yet it is a prized material for LEDs and gallium arsenide semiconductors. It rides along in bauxite ore and is not cheap, and liquid gallium eats through aluminum, so choose the container carefully. Glassworks use it for low-melting seals, and old instrument shops still keep its recipe.", MeltC = 29.8, BoilC = 2399.8, Density = 5.91, Electronegativity = 1.81 },
            new ElementDef { Number = 32, Symbol = "Ge", NameZh = "锗", NameEn = "Germanium", Category = "metalloid", Mass = 72.63, Value = 65, Group = 14, Period = 4, Phase = "Solid", Block = "p", ElectronConfig = "[Ar] 3d10 4s2 4p2", DensityUnit = "g/cm3", DiscoveredBy = "Clemens Winkler", NamedBy = "", SummaryZh = "锗做过世界上第一批晶体管，如今更多用在光纤、红外镜头和太阳能电池里。它从锌矿渣中回收，地壳含量极低，高纯锗是探测器材料，当铺按纯度给价。早年的收音机里塞着它，如今被芯片挤到边角。", SummaryEn = "Germanium powered some of the first transistors and now works in fiber optics, infrared lenses and solar cells. Recovered from zinc residues and extremely dilute in the crust, high-purity germanium is detector material, and the shop prices it by purity. Old radios were full of it, and today the chip trade has pushed it to the margins.", MeltC = 938.3, BoilC = 2832.8, Density = 5.32, Electronegativity = 2.01 },
            new ElementDef { Number = 33, Symbol = "As", NameZh = "砷", NameEn = "Arsenic", Category = "metalloid", Mass = 74.922, Value = 25, Group = 15, Period = 4, Phase = "Solid", Block = "p", ElectronConfig = "[Ar] 3d10 4s2 4p3", DensityUnit = "g/cm3", DiscoveredBy = "Bronze Age", NamedBy = "", SummaryZh = "砒霜的原料，古代最出名的毒药之一，如今三氧化二砷还能治某些白血病。砷化镓是高频芯片材料，地下水里的砷污染是真实的公共危机。旧木材防腐剂里曾经常见它，拆老房子要当心。", SummaryEn = "The raw material of arsenic trioxide, one of history's most famous poisons, which still treats a form of leukemia today. Gallium arsenide is a high-frequency chip material, and arsenic in groundwater is a real public crisis. Old wood preservatives were full of it, so mind yourself when tearing down old houses.", MeltC = 816.9, Density = 5.73, Electronegativity = 2.18 },
            new ElementDef { Number = 34, Symbol = "Se", NameZh = "硒", NameEn = "Selenium", Category = "nonmetal", Mass = 78.971, Value = 38, Group = 16, Period = 4, Phase = "Solid", Block = "p", ElectronConfig = "[Ar] 3d10 4s2 4p4", DensityUnit = "g/cm3", DiscoveredBy = "Jöns Jakob Berzelius", NamedBy = "", SummaryZh = "硒能导电又对光敏感，早年撑起复印机和光敏电阻。它是人体必需的微量元素，缺了会得病，过量却会掉头发中毒，玻璃工业还拿它染红棕色。光敏特性让它成为早期测光表的核心，暗房师傅最懂它。", SummaryEn = "Selenium conducts electricity and reacts to light, which once made xerography and photoresistors possible. It is an essential trace nutrient that causes illness when missing and poisoning when excessive, and glassmakers use it for a red-brown tint. Its light sensitivity made it the heart of early light meters, and darkroom hands know it best.", MeltC = 220.9, BoilC = 684.9, Density = 4.81, Electronegativity = 2.55 },
            new ElementDef { Number = 35, Symbol = "Br", NameZh = "溴", NameEn = "Bromine", Category = "halogen", Mass = 79.904, Value = 30, Group = 17, Period = 4, Phase = "Liquid", Block = "p", ElectronConfig = "[Ar] 3d10 4s2 4p5", DensityUnit = "g/cm3", DiscoveredBy = "Antoine Jérôme Balard", NamedBy = "", SummaryZh = "常温下唯一呈液态的非金属，红棕色、气味刺鼻、蒸气有毒。溴化物做过镇静剂，阻燃剂和感光材料里也常见，海水和盐湖里能提取，腐蚀性很强。药房里的溴剂如今少了，但水处理和钻井液还用它。", SummaryEn = "The only nonmetal that is liquid at room temperature, red-brown, reeking and toxic as a vapor. Bromides once calmed patients, flame retardants and photographic film still use it, and it is extracted from seawater and salt lakes, corrosive to most things it touches. Bromide sedatives have faded from pharmacies, but water treatment and drilling fluids still use it.", MeltC = -7.3, BoilC = 58.9, Density = 3.1, Electronegativity = 2.96 },
            new ElementDef { Number = 36, Symbol = "Kr", NameZh = "氪", NameEn = "Krypton", Category = "noble_gas", Mass = 83.798, Value = 60, Group = 18, Period = 4, Phase = "Gas", Block = "p", ElectronConfig = "[Ar] 3d10 4s2 4p6", DensityUnit = "g/L", DiscoveredBy = "William Ramsay", NamedBy = "", SummaryZh = "氪是从液态空气残气里抓出来的惰性气体，名字本意是隐藏。它用来填高档灯管和激光器，放射性氪八十五可作示踪剂，量少价高，废土上算冷门尖货。它填进中空玻璃里隔热，也能替高级灯泡省电。", SummaryEn = "Krypton is a noble gas pulled from the leftovers of liquid air, and its name means hidden. It fills premium lamps and lasers, radioactive krypton eighty-five serves as a tracer, and supplies are small and pricey, a niche luxury in the wasteland. It fills insulated glazing to trap heat and helps premium bulbs save power.", MeltC = -157.4, BoilC = -153.2, Density = 3.75, Electronegativity = 3.0 },
            new ElementDef { Number = 37, Symbol = "Rb", NameZh = "铷", NameEn = "Rubidium", Category = "alkali_metal", Mass = 85.468, Value = 36, Group = 1, Period = 5, Phase = "Solid", Block = "s", ElectronConfig = "[Kr] 5s1", DensityUnit = "g/cm3", DiscoveredBy = "Robert Bunsen", NamedBy = "", SummaryZh = "铷极其活泼，遇水就炸，名字来自它光谱里的深红色。铷原子钟精度极高，也用于特种玻璃和真空管，地壳里不算稀但分散，很难单独开采。实验室里用它做原子磁强计，废土上没几个人认得。", SummaryEn = "Rubidium is violently reactive and bursts on contact with water, and its name comes from the deep red lines in its spectrum. Rubidium clocks keep extraordinary time, and it also goes into special glass and vacuum tubes; the crust holds plenty but scattered, hard to mine alone. Labs use it in atomic magnetometers, and few in the wasteland would recognize it.", MeltC = 39.3, BoilC = 687.9, Density = 1.53, Electronegativity = 0.82 },
            new ElementDef { Number = 38, Symbol = "Sr", NameZh = "锶", NameEn = "Strontium", Category = "alkaline_earth", Mass = 87.62, Value = 34, Group = 2, Period = 5, Phase = "Solid", Block = "s", ElectronConfig = "[Kr] 5s2", DensityUnit = "g/cm3", DiscoveredBy = "William Cruickshank (chemist)", NamedBy = "", SummaryZh = "锶盐烧起来是鲜艳的红色，烟花和信号弹因此爱用它。锶九十是核裂变产物，会沉积在骨骼里，天然锶则用于铁氧体磁铁和玻璃，毒性不算高。老式显像管玻璃里也掺过它，拆旧电视得防着点。", SummaryEn = "Strontium salts burn a brilliant red, which is why fireworks and signal flares love them. Strontium ninety is a fission product that settles in bone, while natural strontium goes into ferrite magnets and glass and is not especially toxic. Old cathode-ray glass was dosed with it, so be careful when stripping old televisions.", MeltC = 776.9, BoilC = 1376.8, Density = 2.64, Electronegativity = 0.95 },
            new ElementDef { Number = 39, Symbol = "Y", NameZh = "钇", NameEn = "Yttrium", Category = "transition_metal", Mass = 88.906, Value = 42, Group = 3, Period = 5, Phase = "Solid", Block = "d", ElectronConfig = "[Kr] 4d1 5s2", DensityUnit = "g/cm3", DiscoveredBy = "Johan Gadolin", NamedBy = "", SummaryZh = "钇是稀土家族的老前辈，名字来自瑞典的小镇伊特比。它给荧光粉、激光晶体和超导材料当配料，也用于耐高温陶瓷，单独提纯不易，按品位计价。陶瓷刀具和假牙里也有它，耐磨又不惹麻烦。", SummaryEn = "Yttrium is an elder of the rare-earth family, named after the Swedish village of Ytterby. It seasons phosphors, laser crystals and superconductors and goes into heat-resistant ceramics, and purifying it alone is hard, so it is priced by grade. Ceramic knives and false teeth contain it too, wear-resistant and unproblematic.", MeltC = 1525.8, BoilC = 2929.8, Density = 4.47, Electronegativity = 1.22 },
            new ElementDef { Number = 40, Symbol = "Zr", NameZh = "锆", NameEn = "Zirconium", Category = "transition_metal", Mass = 91.224, Value = 44, Group = 4, Period = 5, Phase = "Solid", Block = "d", ElectronConfig = "[Kr] 4d2 5s2", DensityUnit = "g/cm3", DiscoveredBy = "Martin Heinrich Klaproth", NamedBy = "", SummaryZh = "锆耐腐蚀又几乎不吸收中子，是核燃料棒包壳的首选。立方氧化锆冒充钻石在废土市场很常见，陶瓷刀具和耐火材料也用它，验货时要分清等级。化学品储罐和海水管路里衬着它，耐蚀得让人放心。", SummaryEn = "Zirconium resists corrosion and barely absorbs neutrons, which makes it the first choice for nuclear fuel cladding. Cubic zirconia passes for diamond all over the wasteland market, and ceramic knives and refractories use it too, so check the grade before buying. Chemical tanks and seawater lines are lined with it, reassuringly corrosion-proof.", MeltC = 1854.8, BoilC = 4376.9, Density = 6.52, Electronegativity = 1.33 },
            new ElementDef { Number = 41, Symbol = "Nb", NameZh = "铌", NameEn = "Niobium", Category = "transition_metal", Mass = 92.906, Value = 50, Group = 5, Period = 5, Phase = "Solid", Block = "d", ElectronConfig = "[Kr] 4d4 5s1", DensityUnit = "g/cm3", DiscoveredBy = "Charles Hatchett", NamedBy = "", SummaryZh = "铌能让钢更强、让超导线在强磁场里工作，核磁共振和粒子加速器都离不开。名字取自希腊神话里流泪的尼俄柏，矿源集中在少数产地，价格波动大。它在合金里只要一点点，就能让整炉钢身价不同。", SummaryEn = "Niobium strengthens steel and lets superconducting wire work in strong magnetic fields, which MRI scanners and particle accelerators require. Its name comes from Niobe of Greek myth, and supply is concentrated in a few places, so prices swing hard. A whisper of it in the melt changes the worth of an entire heat of steel.", MeltC = 2476.8, BoilC = 4743.9, Density = 8.57, Electronegativity = 1.6 },
            new ElementDef { Number = 42, Symbol = "Mo", NameZh = "钼", NameEn = "Molybdenum", Category = "transition_metal", Mass = 95.95, Value = 46, Group = 6, Period = 5, Phase = "Solid", Block = "d", ElectronConfig = "[Kr] 4d5 5s1", DensityUnit = "g/cm3", DiscoveredBy = "Carl Wilhelm Scheele", NamedBy = "", SummaryZh = "钼能大幅提高钢的高温强度和耐磨性，是合金钢的常客。它还是固氮酶的核心，参与豆科植物固氮；二硫化钼是耐高温润滑剂，粉末和粉尘需防护。化验室拿它做比色试剂，一点蓝色就能读出含量。", SummaryEn = "Molybdenum sharply raises the high-temperature strength and wear resistance of steel, a staple of alloy steels. It also sits at the heart of nitrogenase in nitrogen-fixing plants, and molybdenum disulfide is a high-temperature lubricant whose dust needs protection. Labs use it as a colorimetric reagent, and a hint of blue reads out the content.", MeltC = 2622.8, BoilC = 4638.9, Density = 10.28, Electronegativity = 2.16 },
            new ElementDef { Number = 43, Symbol = "Tc", NameZh = "锝", NameEn = "Technetium", Category = "transition_metal", Mass = 98.0, Value = 180, Group = 7, Period = 5, Phase = "Solid", Block = "d", ElectronConfig = "[Kr] 4d5 5s2", DensityUnit = "g/cm3", DiscoveredBy = "Emilio Segrè", NamedBy = "", SummaryZh = "锝是第一个人工合成的元素，所有同位素都带放射性，自然界几乎找不到。它的亚稳态同位素是核医学显像的主力，半衰期短得现产现用，属于严格管制品。它在钢铁防腐研究里当过示踪剂，帮人看清锈是怎么长出来的。", SummaryEn = "Technetium was the first element made by humans, and every isotope is radioactive, so nature barely holds any. Its metastable isotope is the workhorse of nuclear medical imaging, its half-life is so short that it must be made on demand, and it is strictly controlled. It has served as a tracer in steel corrosion studies, showing how rust takes hold.", MeltC = 2156.8, BoilC = 4264.9, Density = 11.0, Electronegativity = 1.9 },
            new ElementDef { Number = 44, Symbol = "Ru", NameZh = "钌", NameEn = "Ruthenium", Category = "transition_metal", Mass = 101.07, Value = 120, Group = 8, Period = 5, Phase = "Solid", Block = "d", ElectronConfig = "[Kr] 4d7 5s1", DensityUnit = "g/cm3", DiscoveredBy = "Karl Ernst Claus", NamedBy = "", SummaryZh = "钌是铂族里低调的一员，硬度高、耐腐蚀，常做电子触点和催化剂。硬盘磁层、染料敏化太阳能电池和化工催化都用它，产量少，当铺认货不认脸。化工塔和电子浆料里都要它，回收得靠酸慢慢泡。", SummaryEn = "Ruthenium is the quiet member of the platinum group, hard, corrosion-proof and often used in electrical contacts and catalysts. Hard-disk magnetic layers, dye-sensitized solar cells and chemical catalysis all use it, and output is small, so the shop judges the goods, not the seller. Chemical towers and electronic pastes want it, and recovery means a slow acid soak.", MeltC = 2333.8, BoilC = 4149.9, Density = 12.45, Electronegativity = 2.2 },
            new ElementDef { Number = 45, Symbol = "Rh", NameZh = "铑", NameEn = "Rhodium", Category = "transition_metal", Mass = 102.91, Value = 200, Group = 9, Period = 5, Phase = "Solid", Block = "d", ElectronConfig = "[Kr] 4d8 5s1", DensityUnit = "g/cm3", DiscoveredBy = "William Hyde Wollaston", NamedBy = "", SummaryZh = "铑是地球上最贵的金属之一，主要用来净化汽车尾气里的氮氧化物。它反光极好，镀层亮得刺眼，也用于热电偶和首饰；产量极低，废催化剂里回收最划算。它的价格比金子还跳，废土上没人拿它当首饰戴。", SummaryEn = "Rhodium is among the most expensive metals on Earth and mainly scrubs nitrogen oxides from car exhaust. Its reflection is blindingly bright, it plates jewelry and makes thermocouples, and with tiny output the smart money recovers it from spent catalysts. Its price swings harder than gold's, and nobody in the wasteland wears it as jewelry.", MeltC = 1963.8, BoilC = 3694.8, Density = 12.41, Electronegativity = 2.28 },
            new ElementDef { Number = 46, Symbol = "Pd", NameZh = "钯", NameEn = "Palladium", Category = "transition_metal", Mass = 106.42, Value = 180, Group = 10, Period = 5, Phase = "Solid", Block = "d", ElectronConfig = "[Kr] 4d10", DensityUnit = "g/cm3", DiscoveredBy = "William Hyde Wollaston", NamedBy = "", SummaryZh = "钯能大量吸收氢气，是催化转换器和化工催化的主力。它比铂便宜些却更轻，牙科、电子接点和首饰都用得上；早年冷聚变的闹剧让它名声大噪。它的氢脆能毁掉管道，化工厂因此又爱又怕。", SummaryEn = "Palladium soaks up hydrogen like a sponge and is a mainstay of catalytic converters and chemical catalysis. Cheaper and lighter than platinum, it also serves dentistry, electrical contacts and jewelry, and the cold-fusion circus of the past made it famous. Its hydrogen embrittlement can ruin a pipeline, which is why chemical plants both love and fear it.", MeltC = 1554.9, BoilC = 2962.8, Density = 12.02, Electronegativity = 2.2 },
            new ElementDef { Number = 47, Symbol = "Ag", NameZh = "银", NameEn = "Silver", Category = "transition_metal", Mass = 107.87, Value = 140, Group = 11, Period = 5, Phase = "Solid", Block = "d", ElectronConfig = "[Kr] 4d10 5s1", DensityUnit = "g/cm3", DiscoveredBy = "", NamedBy = "", SummaryZh = "导电和导热都是金属里顶尖的，反光率极高，所以镜子、感光胶片和高端电路都要它。银离子能杀菌，银器发黑是硫化，废土上银币依旧硬通货。首饰铺把它和铜一掺，硬度上来，成色就得打折。", SummaryEn = "Silver conducts heat and electricity better than almost any metal and reflects light superbly, so mirrors, film and high-end circuits all want it. Silver ions kill germs, silverware blackens from sulfur, and silver coins remain hard currency in the wasteland. Jewelers cut it with copper for hardness, and the purity then has to be discounted.", MeltC = 961.8, BoilC = 2161.8, Density = 10.49, Electronegativity = 1.93 },
            new ElementDef { Number = 48, Symbol = "Cd", NameZh = "镉", NameEn = "Cadmium", Category = "transition_metal", Mass = 112.41, Value = 36, Group = 12, Period = 5, Phase = "Solid", Block = "d", ElectronConfig = "[Kr] 4d10 5s2", DensityUnit = "g/cm3", DiscoveredBy = "Karl Samuel Leberecht Hermann", NamedBy = "Isotopes of cadmium", SummaryZh = "镉柔软有毒，镍镉电池、颜料和量子点里常见它的身影。它会累积在肾脏和骨骼，日本曾因镉污染爆发痛痛病，废料绝对不能随便埋。电池贩子问价先问它，检测员问价先问有没有它。", SummaryEn = "Cadmium is soft, toxic and common in nickel-cadmium batteries, pigments and quantum dots. It accumulates in kidneys and bones, Japan once suffered the itai-itai disease from cadmium pollution, and cadmium waste must never be buried casually. Battery traders ask for it first, and inspectors ask whether it is in there at all.", MeltC = 321.1, BoilC = 766.9, Density = 8.65, Electronegativity = 1.69 },
            new ElementDef { Number = 49, Symbol = "In", NameZh = "铟", NameEn = "Indium", Category = "post_transition", Mass = 114.82, Value = 50, Group = 13, Period = 5, Phase = "Solid", Block = "p", ElectronConfig = "[Kr] 4d10 5s2 5p1", DensityUnit = "g/cm3", DiscoveredBy = "Ferdinand Reich", NamedBy = "", SummaryZh = "铟软得像蜡，主要用来做触摸屏和显示屏的透明导电膜。它没有独立矿，只能从锌矿副产品里抠出来，用量少却无可替代，废屏幕是重要的回收来源。它也是低温焊料的配方之一，芯片封装离不开。", SummaryEn = "Indium is soft as wax and mainly goes into the transparent conductive film of touchscreens and displays. It has no mine of its own and is scraped from zinc byproducts, tiny in volume but irreplaceable, and dead screens are a key recycling source. It is also part of low-temperature solder recipes, indispensable in chip packaging.", MeltC = 156.6, BoilC = 2071.8, Density = 7.31, Electronegativity = 1.78 },
            new ElementDef { Number = 50, Symbol = "Sn", NameZh = "锡", NameEn = "Tin", Category = "post_transition", Mass = 118.71, Value = 24, Group = 14, Period = 5, Phase = "Solid", Block = "p", ElectronConfig = "[Kr] 4d10 5s2 5p2", DensityUnit = "g/cm3", DiscoveredBy = "", NamedBy = "", SummaryZh = "锡和铜熔在一起就是青铜，人类文明的青铜时代靠它开场。焊锡、马口铁罐头和镀锡层到处都有，低温下会碎成粉末的锡疫是它的老毛病。钟、管风琴和轴承合金里都有它的声音和脾气。", SummaryEn = "Tin melted with copper gives bronze, and the Bronze Age opened with that recipe. Solder, tinplate cans and tin coatings are everywhere, and its old curse is tin pest, which crumbles the metal to powder in the cold. Bells, pipe organs and bearing alloys all carry its voice and temperament.", MeltC = 231.9, BoilC = 2601.8, Density = 7.37, Electronegativity = 1.96 },
            new ElementDef { Number = 51, Symbol = "Sb", NameZh = "锑", NameEn = "Antimony", Category = "metalloid", Mass = 121.76, Value = 30, Group = 15, Period = 5, Phase = "Solid", Block = "p", ElectronConfig = "[Kr] 4d10 5s2 5p3", DensityUnit = "g/cm3", DiscoveredBy = "", NamedBy = "", SummaryZh = "锑古时候被磨成粉当眼影，如今主要用来做阻燃剂和铅酸电池的合金。它性脆、导热差，化合物有毒，长期接触会伤肝和心脏，属于要登记的危化品。它的硫化物是天然辉锑矿，矿工见它像见老朋友。", SummaryEn = "Antimony was ground into eye makeup in antiquity and today mainly makes flame retardants and lead-acid battery alloys. It is brittle and a poor conductor, its compounds are toxic, long exposure damages liver and heart, and it is a registered hazardous chemical. Its sulfide is the natural mineral stibnite, and miners greet it like an old friend.", MeltC = 630.6, BoilC = 1634.8, Density = 6.7, Electronegativity = 2.05 },
            new ElementDef { Number = 52, Symbol = "Te", NameZh = "碲", NameEn = "Tellurium", Category = "metalloid", Mass = 127.6, Value = 55, Group = 16, Period = 5, Phase = "Solid", Block = "p", ElectronConfig = "[Kr] 4d10 5s2 5p4", DensityUnit = "g/cm3", DiscoveredBy = "Franz-Joseph Müller von Reichenstein", NamedBy = "", SummaryZh = "碲让铜更好切削，也让碲化镉薄膜太阳能板能发电。它比铂还稀有，却大量用在红外探测和热电材料上；碲化物有毒性，接触后呼气会带蒜味。它把玻璃染成蓝褐色，也进红外光纤当配料。", SummaryEn = "Tellurium makes copper easier to machine and lets cadmium telluride thin-film solar panels generate power. Rarer than platinum yet used heavily in infrared detection and thermoelectrics, its compounds are toxic and exposure leaves garlic breath. It tints glass blue-brown and goes into infrared fiber as an ingredient.", MeltC = 449.5, BoilC = 987.9, Density = 6.24, Electronegativity = 2.1 },
            new ElementDef { Number = 53, Symbol = "I", NameZh = "碘", NameEn = "Iodine", Category = "halogen", Mass = 126.9, Value = 28, Group = 17, Period = 5, Phase = "Solid", Block = "p", ElectronConfig = "[Kr] 4d10 5s2 5p5", DensityUnit = "g/cm3", DiscoveredBy = "Bernard Courtois", NamedBy = "", SummaryZh = "碘是甲状腺合成激素的原料，缺了会得大脖子病，所以食盐里要加碘。它加热会直接升华成紫色蒸气，碘酒和碘伏是废土上最常用的消毒货。碘化银曾经撒进云里求雨，如今只在旧气象站听得到。", SummaryEn = "Iodine is the raw material for thyroid hormones, and its lack causes goiter, which is why salt is iodized. Heated, it sublimes straight into violet vapor, and iodine tincture and iodophor are the wasteland's most common disinfectants. Silver iodide was once seeded into clouds for rain, a story now heard only at old weather stations.", MeltC = 113.7, BoilC = 184.2, Density = 4.93, Electronegativity = 2.66 },
            new ElementDef { Number = 54, Symbol = "Xe", NameZh = "氙", NameEn = "Xenon", Category = "noble_gas", Mass = 131.29, Value = 75, Group = 18, Period = 5, Phase = "Gas", Block = "p", ElectronConfig = "[Kr] 4d10 5s2 5p6", DensityUnit = "g/L", DiscoveredBy = "William Ramsay", NamedBy = "", SummaryZh = "氙气灯亮得接近日光，还用于离子推进器和麻醉。它从液态空气里提取，产量很少价格不低；氙的放射性同位素能做肺功能检查，属于精细货。液体氙还是粒子探测器里的介质，暗物质实验正找它。", SummaryEn = "Xenon lamps shine almost like daylight, and the gas also drives ion thrusters and anesthesia. Extracted from liquid air in small amounts, it is not cheap, and radioactive xenon isotopes check lung function, making it a fine-grade good. Liquid xenon is a detector medium too, and dark-matter experiments are hunting with it.", MeltC = -111.7, BoilC = -108.1, Density = 5.89, Electronegativity = 2.6 },
            new ElementDef { Number = 55, Symbol = "Cs", NameZh = "铯", NameEn = "Cesium", Category = "alkali_metal", Mass = 132.91, Value = 32, Group = 1, Period = 6, Phase = "Solid", Block = "s", ElectronConfig = "[Xe] 6s1", DensityUnit = "g/cm3", DiscoveredBy = "Robert Bunsen", NamedBy = "", SummaryZh = "铯是最活泼的金属之一，遇水立刻爆炸，熔点低到用手就能化开。铯原子钟定义了秒的长度，放射性铯一百三十七是核事故后最麻烦的污染物。它在光电管里一见光就放电，老式测光表靠它。", SummaryEn = "Cesium is one of the most reactive metals, exploding on water and melting low enough to liquefy in a warm hand. Cesium clocks define the length of the second, and radioactive cesium one thirty-seven is the nastiest contaminant left after a nuclear accident. It discharges at the first light in a photocell, and old light meters ran on it.", MeltC = 28.6, BoilC = 670.9, Density = 1.93, Electronegativity = 0.79 },
            new ElementDef { Number = 56, Symbol = "Ba", NameZh = "钡", NameEn = "Barium", Category = "alkaline_earth", Mass = 137.33, Value = 28, Group = 2, Period = 6, Phase = "Solid", Block = "s", ElectronConfig = "[Xe] 6s2", DensityUnit = "g/cm3", DiscoveredBy = "Carl Wilhelm Scheele", NamedBy = "", SummaryZh = "硫酸钡不溶于水，喝下去能当 X 光造影剂，所以叫钡餐。可溶性钡盐有剧毒，会让人肌肉麻痹；钡盐还用来做绿色烟花和钻井泥浆。玻璃厂拿它提高折射率，光学镜片里能见到。", SummaryEn = "Barium sulfate does not dissolve, so patients drink it as an X-ray contrast agent, the famous barium meal. Soluble barium salts are violently toxic and paralyze muscles, while barium salts also color green fireworks and thicken drilling mud. Glassworks use it to raise the refractive index, and optical lenses contain it.", MeltC = 726.9, BoilC = 1844.8, Density = 3.51, Electronegativity = 0.89 },
            new ElementDef { Number = 57, Symbol = "La", NameZh = "镧", NameEn = "Lanthanum", Category = "lanthanide", Mass = 138.91, Value = 50, Group = 0, Period = 6, Phase = "Solid", Block = "f", ElectronConfig = "[Xe] 5d1 6s2", DensityUnit = "g/cm3", DiscoveredBy = "Carl Gustaf Mosander", NamedBy = "", SummaryZh = "镧是稀土里打头的一个，名字本意是隐藏。它加进光学玻璃能提高折射率，镍氢电池和石油裂化催化剂也离不开；产量不小，但提纯费电费酸。它在荧光粉和陶瓷电容里也有份，行家一眼就认得。", SummaryEn = "Lanthanum is the opening act of the rare earths, and its name means to lie hidden. Added to optical glass it raises the refractive index, and nickel-metal-hydride batteries and oil-cracking catalysts need it too; output is decent but refining burns power and acid. It has a share in phosphors and ceramic capacitors, and experts spot it at a glance.", MeltC = 919.9, BoilC = 3463.8, Density = 6.16, Electronegativity = 1.1 },
            new ElementDef { Number = 58, Symbol = "Ce", NameZh = "铈", NameEn = "Cerium", Category = "lanthanide", Mass = 140.12, Value = 48, Group = 0, Period = 6, Phase = "Solid", Block = "f", ElectronConfig = "[Xe] 4f1 5d1 6s2", DensityUnit = "g/cm3", DiscoveredBy = "Martin Heinrich Klaproth", NamedBy = "", SummaryZh = "铈是储量最丰富的稀土，打火石里那点火星就是它。它抛光玻璃、净化汽车尾气、给陶瓷上色，还能做自燃合金；放射性伴生矿要按规矩处理。它在铝合金和镁合金里当细化剂，铸件才不容易裂。", SummaryEn = "Cerium is the most abundant rare earth, and the sparks off a lighter flint are largely it. It polishes glass, cleans car exhaust, colors ceramics and makes self-igniting alloys, and its radioactive companion ores must be handled by the rules. It refines the grain in aluminum and magnesium alloys so castings do not crack.", MeltC = 794.9, BoilC = 3442.8, Density = 6.77, Electronegativity = 1.12 },
            new ElementDef { Number = 59, Symbol = "Pr", NameZh = "镨", NameEn = "Praseodymium", Category = "lanthanide", Mass = 140.91, Value = 70, Group = 0, Period = 6, Phase = "Solid", Block = "f", ElectronConfig = "[Xe] 4f3 6s2", DensityUnit = "g/cm3", DiscoveredBy = "Carl Auer von Welsbach", NamedBy = "", SummaryZh = "镨和钕是老搭档，一个管绿色一个管紫红，彩色玻璃和陶瓷釉色里常见。它用于强磁体和焊工护目镜，能滤掉刺眼的黄光，纯品在市场上不算便宜。它给光纤放大器当掺杂剂，通信行当也认它。", SummaryEn = "Praseodymium and neodymium are old partners, one coloring glass green and the other violet-red, common in colored glass and ceramic glazes. It strengthens magnets and filters the glare in welders' goggles, and pure material is not cheap on the open market. It dopes fiber amplifiers, and the communications trade knows it too.", MeltC = 934.9, BoilC = 3129.8, Density = 6.77, Electronegativity = 1.13 },
            new ElementDef { Number = 60, Symbol = "Nd", NameZh = "钕", NameEn = "Neodymium", Category = "lanthanide", Mass = 144.24, Value = 75, Group = 0, Period = 6, Phase = "Solid", Block = "f", ElectronConfig = "[Xe] 4f4 6s2", DensityUnit = "g/cm3", DiscoveredBy = "Carl Auer von Welsbach", NamedBy = "", SummaryZh = "钕铁硼是目前最强的永磁材料，耳机、电机和风力发电机都靠它。钕玻璃能放大激光，掺钕晶体是固体激光器的核心，稀土管制一紧价格就飞。它的磁体让旧硬盘转得又稳又久，拆机货最抢手。", SummaryEn = "Neodymium-iron-boron is the strongest permanent magnet known, and headphones, motors and wind turbines depend on it. Neodymium glass amplifies laser light and neodymium-doped crystals are the core of solid-state lasers, so rare-earth export controls send its price flying. Its magnets keep old hard drives spinning steady and long, so salvaged units sell fast.", MeltC = 1023.9, BoilC = 3073.8, Density = 7.01, Electronegativity = 1.14 },
            new ElementDef { Number = 61, Symbol = "Pm", NameZh = "钷", NameEn = "Promethium", Category = "lanthanide", Mass = 145.0, Value = 180, Group = 0, Period = 6, Phase = "Solid", Block = "f", ElectronConfig = "[Xe] 4f5 6s2", DensityUnit = "g/cm3", DiscoveredBy = "Chien Shiung Wu", NamedBy = "Isotopes of promethium", SummaryZh = "钷是镧系里唯一没有稳定同位素的成员，天然几乎不存在。它靠核反应堆副产物提取，早年用于夜光涂料和微型核电池，如今更多是研究用途。它在废土上没有买家，只有研究所肯为它开价。", SummaryEn = "Promethium is the only lanthanide with no stable isotope, and nature holds almost none. Recovered as a reactor byproduct, it once lit luminous paint and powered tiny nuclear batteries, and today it is mostly a research material. No buyer in the wasteland wants it; only research institutes name a price.", MeltC = 1041.8, BoilC = 2999.8, Density = 7.26, Electronegativity = 1.13 },
            new ElementDef { Number = 62, Symbol = "Sm", NameZh = "钐", NameEn = "Samarium", Category = "lanthanide", Mass = 150.36, Value = 85, Group = 0, Period = 6, Phase = "Solid", Block = "f", ElectronConfig = "[Xe] 4f6 6s2", DensityUnit = "g/cm3", DiscoveredBy = "Lecoq de Boisbaudran", NamedBy = "", SummaryZh = "钐钴磁铁耐高温，是航空航天和军工的老牌选择。钐还能强烈吸收中子，做反应堆控制材料；它也是早期治疗骨转移疼痛的放射性药物来源。它的价格跟着稀土行情走，囤货商最爱这种小品种。", SummaryEn = "Samarium-cobalt magnets hold up at high temperature, a veteran choice for aerospace and defense. Samarium also absorbs neutrons strongly for reactor control, and it is the source of an early radiopharmaceutical for bone-metastasis pain. Its price follows the rare-earth market, and hoarders love such small-volume lines.", MeltC = 1071.8, BoilC = 1899.8, Density = 7.52, Electronegativity = 1.17 },
            new ElementDef { Number = 63, Symbol = "Eu", NameZh = "铕", NameEn = "Europium", Category = "lanthanide", Mass = 151.96, Value = 90, Group = 0, Period = 6, Phase = "Solid", Block = "f", ElectronConfig = "[Xe] 4f7 6s2", DensityUnit = "g/cm3", DiscoveredBy = "Eugène-Anatole Demarçay", NamedBy = "", SummaryZh = "铕的红色荧光粉让老式显像管屏幕能显示纯正红色，欧元纸币的防伪也用它。它吸收中子能力强，反应堆控制棒里有它的位置；产量小，价格敏感。它的化合物在紫外下会亮，实验室拿它做荧光探针。", SummaryEn = "Europium's red phosphor gave old cathode-ray screens their true red, and euro banknotes use it against forgery. It absorbs neutrons well enough to sit in reactor control rods, and output is small, so its price is sensitive. Its compounds light up under ultraviolet, and labs use it as a fluorescent probe.", MeltC = 825.9, BoilC = 1528.8, Density = 5.26, Electronegativity = 1.2 },
            new ElementDef { Number = 64, Symbol = "Gd", NameZh = "钆", NameEn = "Gadolinium", Category = "lanthanide", Mass = 157.25, Value = 88, Group = 0, Period = 6, Phase = "Solid", Block = "f", ElectronConfig = "[Xe] 4f7 5d1 6s2", DensityUnit = "g/cm3", DiscoveredBy = "Jean Charles Galissard de Marignac", NamedBy = "", SummaryZh = "钆的顺磁性让它成为核磁共振造影剂的主角，注射后能让图像更清楚。它吸收中子极强，也用于反应堆和辐射屏蔽；名字来自芬兰化学家加多林。它的磁制冷效应能让低温实验少用点液氦。", SummaryEn = "Gadolinium's paramagnetism makes it the star of MRI contrast agents, injected to sharpen the image. It also absorbs neutrons extremely well for reactors and radiation shielding, and its name honors the Finnish chemist Gadolin. Its magnetic refrigeration can cut the liquid helium a cryogenic lab needs.", MeltC = 1311.8, BoilC = 2999.8, Density = 7.9, Electronegativity = 1.2 },
            new ElementDef { Number = 65, Symbol = "Tb", NameZh = "铽", NameEn = "Terbium", Category = "lanthanide", Mass = 158.93, Value = 95, Group = 0, Period = 6, Phase = "Solid", Block = "f", ElectronConfig = "[Xe] 4f9 6s2", DensityUnit = "g/cm3", DiscoveredBy = "Carl Gustaf Mosander", NamedBy = "", SummaryZh = "铽在磁场里会微微伸缩，这种磁致伸缩效应让它成为声呐和水下探测的关键材料。绿色荧光粉、磁光存储和燃料电池也用它，属于重稀土里的紧俏货。它也是绿色激光和荧光标记的常用掺杂，实验台上常备。", SummaryEn = "Terbium stretches and shrinks slightly in a magnetic field, and that magnetostriction makes it key to sonar and underwater detection. Green phosphors, magneto-optical storage and fuel cells use it too, a tight commodity among the heavy rare earths. It is a common dopant for green lasers and fluorescent tags, kept close on the bench.", MeltC = 1355.8, BoilC = 3122.8, Density = 8.23, Electronegativity = 1.1 },
            new ElementDef { Number = 66, Symbol = "Dy", NameZh = "镝", NameEn = "Dysprosium", Category = "lanthanide", Mass = 162.5, Value = 100, Group = 0, Period = 6, Phase = "Solid", Block = "f", ElectronConfig = "[Xe] 4f10 6s2", DensityUnit = "g/cm3", DiscoveredBy = "Lecoq de Boisbaudran", NamedBy = "", SummaryZh = "镝加进钕铁硼磁体里，能让磁铁在高温下不退磁，电动车和风机都离不开。它几乎全从南方离子型稀土矿里来，供应紧张时价格能翻好几倍。它在核反应堆控制棒里也有一席，吸中子不手软。", SummaryEn = "A little dysprosium keeps neodymium magnets from losing strength when hot, and electric cars and wind turbines cannot do without it. It comes almost entirely from southern ionic clay deposits, and when supply tightens the price can multiply. It also holds a seat in reactor control rods, swallowing neutrons without flinching.", MeltC = 1406.8, BoilC = 2566.8, Density = 8.54, Electronegativity = 1.22 },
            new ElementDef { Number = 67, Symbol = "Ho", NameZh = "钬", NameEn = "Holmium", Category = "lanthanide", Mass = 164.93, Value = 105, Group = 0, Period = 6, Phase = "Solid", Block = "f", ElectronConfig = "[Xe] 4f11 6s2", DensityUnit = "g/cm3", DiscoveredBy = "Marc Delafontaine", NamedBy = "", SummaryZh = "钬的磁矩在元素里数一数二，能把磁场聚得极强。钬激光在泌尿科碎石和眼科手术里很常用，掺钬晶体也用于科研；玻璃里加它呈淡黄色，产量稀少。它在强磁场实验里当极化的靶材，物理学家才用得起。", SummaryEn = "Holmium has one of the strongest magnetic moments of any element and concentrates magnetic fields sharply. Holmium lasers are routine in kidney stone work and eye surgery, holmium-doped crystals serve research, and its glass tints pale yellow; output is tiny. It serves as a polarized target in strong-field experiments, affordable only to physicists.", MeltC = 1460.8, BoilC = 2599.8, Density = 8.79, Electronegativity = 1.23 },
            new ElementDef { Number = 68, Symbol = "Er", NameZh = "铒", NameEn = "Erbium", Category = "lanthanide", Mass = 167.26, Value = 98, Group = 0, Period = 6, Phase = "Solid", Block = "f", ElectronConfig = "[Xe] 4f12 6s2", DensityUnit = "g/cm3", DiscoveredBy = "Carl Gustaf Mosander", NamedBy = "", SummaryZh = "铒的光学特性让它成为光纤通信的放大器核心，掺铒光纤让信号能横跨大洋。它给玻璃染成粉色，也用于激光测距和医疗激光，属于重稀土中的实用派。它的同位素曾注射进关节治炎症，核医学科的老账本记着。", SummaryEn = "Erbium's optical behavior makes it the heart of fiber-optic amplifiers, letting signals cross oceans. It tints glass pink and serves laser rangefinders and medical lasers, an eminently practical member of the heavy rare earths. Isotopes of it were injected into joints to calm inflammation, as old nuclear medicine ledgers recall.", MeltC = 1528.8, BoilC = 2867.8, Density = 9.07, Electronegativity = 1.24 },
            new ElementDef { Number = 69, Symbol = "Tm", NameZh = "铥", NameEn = "Thulium", Category = "lanthanide", Mass = 168.93, Value = 110, Group = 0, Period = 6, Phase = "Solid", Block = "f", ElectronConfig = "[Xe] 4f13 6s2", DensityUnit = "g/cm3", DiscoveredBy = "Per Teodor Cleve", NamedBy = "", SummaryZh = "铥是天然稀土里最稀少的一个，却有一手绝活：做便携式 X 射线源。它的蓝色荧光和激光也有用处，提纯难度大，当铺里见到基本都是实验室流出。它在光纤激光器里能切金属，也能给医疗设备打标。", SummaryEn = "Thulium is the scarcest of the natural rare earths, yet it has a trick: portable X-ray sources. Its blue glow and lasers have their uses too, and purifying it is hard, so anything in the shop probably leaked out of a lab. In fiber lasers it cuts metal and marks medical devices.", MeltC = 1544.8, BoilC = 1949.8, Density = 9.32, Electronegativity = 1.25 },
            new ElementDef { Number = 70, Symbol = "Yb", NameZh = "镱", NameEn = "Ytterbium", Category = "lanthanide", Mass = 173.05, Value = 92, Group = 0, Period = 6, Phase = "Solid", Block = "f", ElectronConfig = "[Xe] 4f14 6s2", DensityUnit = "g/cm3", DiscoveredBy = "Jean Charles Galissard de Marignac", NamedBy = "", SummaryZh = "镱能做成极精确的光晶格原子钟，也可能成为下一代时钟的基础。它掺进光纤激光器和不锈钢里改善性能，还用于应力测量；价格在重稀土里相对温和。它在核医学里也能当示踪剂，医院偶尔会订。", SummaryEn = "Ytterbium can build staggeringly precise optical lattice clocks that may become the next generation of timekeeping. Doped into fiber lasers and stainless steel it improves performance, it measures stress, and its price is mild among the heavy rare earths. It can serve as a tracer in nuclear medicine, and hospitals order it now and then.", MeltC = 823.9, BoilC = 1195.8, Density = 6.9, Electronegativity = 1.1 },
            new ElementDef { Number = 71, Symbol = "Lu", NameZh = "镥", NameEn = "Lutetium", Category = "lanthanide", Mass = 174.97, Value = 120, Group = 0, Period = 6, Phase = "Solid", Block = "d", ElectronConfig = "[Xe] 4f14 5d1 6s2", DensityUnit = "g/cm3", DiscoveredBy = "Georges Urbain", NamedBy = "", SummaryZh = "镥是镧系里最重最硬的一位，密度大、熔点高。它的同位素用于正电子发射断层扫描的探测器晶体，也做石油裂化催化剂；产量少，属于贵价稀土。它是最贵的稀土之一，回收靶材比开矿划算。", SummaryEn = "Lutetium is the heaviest and hardest of the lanthanides, dense and high-melting. Its isotopes go into the detector crystals of PET scanners and into oil-cracking catalysts, and with little output it counts as a costly rare earth. It is among the costliest rare earths, and recycling targets beats mining it.", MeltC = 1651.8, BoilC = 3401.8, Density = 9.84, Electronegativity = 1.27 },
            new ElementDef { Number = 72, Symbol = "Hf", NameZh = "铪", NameEn = "Hafnium", Category = "transition_metal", Mass = 178.49, Value = 80, Group = 4, Period = 6, Phase = "Solid", Block = "d", ElectronConfig = "[Xe] 4f14 5d2 6s2", DensityUnit = "g/cm3", DiscoveredBy = "Dirk Coster", NamedBy = "", SummaryZh = "铪和锆在矿石里形影不离，却是中子吸收的高手，所以核反应堆控制棒用它。芯片里做高介电栅极，超合金和等离子切割也离不开；提纯分离非常麻烦。它和锆的价差大得离谱，收货时别被当成锆称走。", SummaryEn = "Hafnium travels inseparably with zirconium in ore yet excels at absorbing neutrons, so reactor control rods use it. Chips use it as a high-dielectric gate, superalloys and plasma cutting need it, and separating it from zirconium is a real headache. Its price gap with zirconium is absurd, so do not let a buyer weigh it as zirconium.", MeltC = 2232.8, BoilC = 4602.9, Density = 13.31, Electronegativity = 1.3 },
            new ElementDef { Number = 73, Symbol = "Ta", NameZh = "钽", NameEn = "Tantalum", Category = "transition_metal", Mass = 180.95, Value = 85, Group = 5, Period = 6, Phase = "Solid", Block = "d", ElectronConfig = "[Xe] 4f14 5d3 6s2", DensityUnit = "g/cm3", DiscoveredBy = "Anders Gustaf Ekeberg", NamedBy = "", SummaryZh = "钽电容体积小容量大，手机和航天电路里到处都是。它极耐腐蚀，做外科植入体和化工设备很合适；名字取自希腊神话里受罚的坦塔罗斯。它在高温合金里当添加剂，喷气叶片也认它。", SummaryEn = "Tantalum capacitors pack large capacity into a tiny volume, which is why phones and space circuits are full of them. It resists corrosion almost totally, suits surgical implants and chemical equipment, and its name comes from the punished Tantalus of Greek myth. It serves as an additive in superalloys, and jet blades accept it too.", MeltC = 3016.8, BoilC = 5457.9, Density = 16.69, Electronegativity = 1.5 },
            new ElementDef { Number = 74, Symbol = "W", NameZh = "钨", NameEn = "Tungsten", Category = "transition_metal", Mass = 183.84, Value = 60, Group = 6, Period = 6, Phase = "Solid", Block = "d", ElectronConfig = "[Xe] 4f14 5d4 6s2", DensityUnit = "g/cm3", DiscoveredBy = "Carl Wilhelm Scheele", NamedBy = "", SummaryZh = "钨是所有金属里熔点最高的，白炽灯丝和焊接电极因此选它。碳化钨硬度接近金刚石，做钻头和穿甲弹芯；名字来自瑞典语的沉重石头，密度大得压手。航天配重和陀螺转子也用它，沉就是它的本钱。", SummaryEn = "Tungsten has the highest melting point of any metal, which is why lamp filaments and welding electrodes are made of it. Tungsten carbide rivals diamond in hardness for drill bits and armor-piercing cores, and its name comes from the Swedish for heavy stone; it sits heavy in the hand. Spacecraft counterweights and gyroscope rotors use it too, where heaviness is the whole point.", MeltC = 3421.8, BoilC = 5929.9, Density = 19.25, Electronegativity = 2.36 },
            new ElementDef { Number = 75, Symbol = "Re", NameZh = "铼", NameEn = "Rhenium", Category = "transition_metal", Mass = 186.21, Value = 110, Group = 7, Period = 6, Phase = "Solid", Block = "d", ElectronConfig = "[Xe] 4f14 5d5 6s2", DensityUnit = "g/cm3", DiscoveredBy = "Masataka Ogawa", NamedBy = "Walter Noddack", SummaryZh = "铼的熔点仅次于钨，是喷气发动机涡轮叶片的关键合金元素。它在地壳里极其稀少，多从钼矿副产品里回收；催化剂和高温热电偶也用它，价格常年坚挺。它在重整催化剂里帮汽油提辛烷值，炼厂离不开。", SummaryEn = "Rhenium's melting point is second only to tungsten's, making it vital to jet engine turbine blades. Extremely scarce in the crust and mostly recovered from molybdenum byproducts, it also serves catalysts and high-temperature thermocouples, and its price stays firm. In reforming catalysts it lifts gasoline octane, and refineries cannot do without it.", MeltC = 3185.8, BoilC = 5595.9, Density = 21.02, Electronegativity = 1.9 },
            new ElementDef { Number = 76, Symbol = "Os", NameZh = "锇", NameEn = "Osmium", Category = "transition_metal", Mass = 190.23, Value = 130, Group = 8, Period = 6, Phase = "Solid", Block = "d", ElectronConfig = "[Xe] 4f14 5d6 6s2", DensityUnit = "g/cm3", DiscoveredBy = "Smithson Tennant", NamedBy = "", SummaryZh = "锇是密度最大的元素，拿在手里沉得吓人。它极硬耐磨，老式钢笔尖和仪表轴承里加过它；锇的氧化物有剧毒且气味刺鼻，接触要格外小心。它的价格高得离谱，废品站老板一辈子也见不到几克。", SummaryEn = "Osmium is the densest element there is and feels startlingly heavy in the hand. Extremely hard and wear-resistant, it went into old fountain pen tips and instrument bearings, and its oxide is viciously toxic and reeks, so keep away. Its price is absurd, and a scrapyard owner sees a few grams in a lifetime.", MeltC = 3032.8, BoilC = 5011.9, Density = 22.59, Electronegativity = 2.2 },
            new ElementDef { Number = 77, Symbol = "Ir", NameZh = "铱", NameEn = "Iridium", Category = "transition_metal", Mass = 192.22, Value = 190, Group = 9, Period = 6, Phase = "Solid", Block = "d", ElectronConfig = "[Xe] 4f14 5d7 6s2", DensityUnit = "g/cm3", DiscoveredBy = "Smithson Tennant", NamedBy = "", SummaryZh = "铱极耐腐蚀、极难熔化，火花塞和高温坩埚里常见它。地层里的铱异常是恐龙灭绝撞击说的关键证据；它比铂还稀有，废催化剂里回收最值钱。它是铂族里最耐蚀的一个，酸洗槽里泡着也不变样。", SummaryEn = "Iridium resists corrosion and melting almost absolutely, common in spark plugs and high-temperature crucibles. The iridium anomaly in rock layers is key evidence for the dinosaur-killing impact, and it is rarer than platinum, so spent catalysts are the richest source. It is the most corrosion-proof of the platinum group, unchanged in an acid bath.", MeltC = 2445.8, BoilC = 4129.9, Density = 22.56, Electronegativity = 2.2 },
            new ElementDef { Number = 78, Symbol = "Pt", NameZh = "铂", NameEn = "Platinum", Category = "transition_metal", Mass = 195.08, Value = 210, Group = 10, Period = 6, Phase = "Solid", Block = "d", ElectronConfig = "[Xe] 4f14 5d9 6s1", DensityUnit = "g/cm3", DiscoveredBy = "Antonio de Ulloa", NamedBy = "", SummaryZh = "铂在珠宝、实验室坩埚和汽车尾气催化里都是老资格。它化学上很稳，能催化很多反应，顺铂还是重要的抗癌药；产量集中在少数国家，价格坚挺。它做电极和喷丝板，玻璃纤维厂的旧件里能刮出不少。", SummaryEn = "Platinum is a veteran of jewelry, lab crucibles and car exhaust catalysis. Chemically very stable and able to catalyze many reactions, cisplatin is also an important anticancer drug, and production sits in a few countries, keeping prices firm. It makes electrodes and spinnerets, and old glass-fiber plant parts yield a good scrape.", MeltC = 1768.2, BoilC = 3824.8, Density = 21.45, Electronegativity = 2.28 },
            new ElementDef { Number = 79, Symbol = "Au", NameZh = "金", NameEn = "Gold", Category = "transition_metal", Mass = 196.97, Value = 220, Group = 11, Period = 6, Phase = "Solid", Block = "d", ElectronConfig = "[Xe] 4f14 5d10 6s1", DensityUnit = "g/cm3", DiscoveredBy = "", NamedBy = "", SummaryZh = "金子化学上几乎不反应，所以能千年不锈，是天然的价值储藏。电子接点、牙科和航天镀层都需要它，废土上黄金仍旧是最好使的硬通货。金箔贴在玻璃上能挡热，航天服的护目镜靠它保命。", SummaryEn = "Gold barely reacts with anything, so it stays bright for millennia and is a natural store of value. Electrical contacts, dentistry and space plating need it, and in the wasteland gold is still the most usable hard currency. Gold foil on glass blocks heat, and space suit visors stay safe because of it.", MeltC = 1064.2, BoilC = 2969.8, Density = 19.3, Electronegativity = 2.54 },
            new ElementDef { Number = 80, Symbol = "Hg", NameZh = "汞", NameEn = "Mercury", Category = "transition_metal", Mass = 200.59, Value = 40, Group = 12, Period = 6, Phase = "Liquid", Block = "d", ElectronConfig = "[Xe] 4f14 5d10 6s2", DensityUnit = "g/cm3", DiscoveredBy = "", NamedBy = "", SummaryZh = "汞是常温下唯一的液态金属，密度大、能溶解许多金属形成汞齐。温度计和血压计曾靠它，如今因毒性被淘汰；日本水俣病就是甲基汞污染造成的。金铺用它把金从矿石里抓出来，汞齐法老了却还管用。", SummaryEn = "Mercury is the only metal that is liquid at room temperature, dense and able to dissolve many metals into amalgams. Thermometers and blood-pressure gauges once depended on it before toxicity drove it out, and Japan's Minamata disease came from methylmercury pollution. Gold shops use it to pull gold from ore, and the old amalgam method still works.", MeltC = -38.8, BoilC = 356.7, Density = 13.53, Electronegativity = 2.0 },
            new ElementDef { Number = 81, Symbol = "Tl", NameZh = "铊", NameEn = "Thallium", Category = "post_transition", Mass = 204.38, Value = 45, Group = 13, Period = 6, Phase = "Solid", Block = "p", ElectronConfig = "[Xe] 4f14 5d10 6s2 6p1", DensityUnit = "g/cm3", DiscoveredBy = "William Crookes", NamedBy = "", SummaryZh = "铊剧毒且无色无味，历史上多次被用于投毒，因此有投毒者之金属的外号。它用于红外探测器和某些心脏显像，工业上也在慢慢被替代，属于严格管控物质。它的盐曾混进灭鼠药，废土上看见无标签白粉先别碰。", SummaryEn = "Thallium is viciously toxic, colorless and tasteless, and history's poisoners loved it, earning it the nickname of the poisoner's metal. It serves infrared detectors and some heart imaging, industry is slowly replacing it, and it is a strictly controlled substance. Its salts once went into rat poison, so leave unlabeled white powder alone in the wastes.", MeltC = 303.9, BoilC = 1472.8, Density = 11.85, Electronegativity = 1.62 },
            new ElementDef { Number = 82, Symbol = "Pb", NameZh = "铅", NameEn = "Lead", Category = "post_transition", Mass = 207.2, Value = 25, Group = 14, Period = 6, Phase = "Solid", Block = "p", ElectronConfig = "[Xe] 4f14 5d10 6s2 6p2", DensityUnit = "g/cm3", DiscoveredBy = "", NamedBy = "", SummaryZh = "铅软、重、易加工，古罗马的水管和今天的蓄电池都用它。它能屏蔽辐射，却会损伤神经系统，尤其害儿童；含铅汽油的历史教训至今还在清算。它的弹头软，打进猎物后变形，猎人偏爱它的重量。", SummaryEn = "Lead is soft, heavy and easy to work, used in Roman plumbing and today's car batteries. It shields radiation yet damages the nervous system, especially in children, and the legacy of leaded gasoline is still being paid off. Its bullets are soft and deform in game, and hunters favor its weight.", MeltC = 327.5, BoilC = 1748.8, Density = 11.34, Electronegativity = 1.87 },
            new ElementDef { Number = 83, Symbol = "Bi", NameZh = "铋", NameEn = "Bismuth", Category = "post_transition", Mass = 208.98, Value = 35, Group = 15, Period = 6, Phase = "Solid", Block = "p", ElectronConfig = "[Xe] 4f14 5d10 6s2 6p3", DensityUnit = "g/cm3", DiscoveredBy = "Claude François Geoffroy", NamedBy = "", SummaryZh = "铋是少见的无毒重金属，铋晶体表面会长出彩虹色的阶梯纹。它做胃药、低熔点合金和焊料，还能替代铅做环保材料；放射性衰变慢到几乎测不出。它的化合物做过化妆品和珠光颜料，无毒是最大卖点。", SummaryEn = "Bismuth is the rare heavy metal that is not toxic, and its crystals grow rainbow-colored staircase patterns. It makes stomach medicine, low-melting alloys and solders, and replaces lead in greener materials; its radioactive decay is so slow it is barely measurable. Its compounds went into cosmetics and pearlescent pigments, and being non-toxic was the selling point.", MeltC = 271.6, BoilC = 1563.8, Density = 9.78, Electronegativity = 2.02 },
            new ElementDef { Number = 84, Symbol = "Po", NameZh = "钋", NameEn = "Polonium", Category = "post_transition", Mass = 209.0, Value = 120, Group = 16, Period = 6, Phase = "Solid", Block = "p", ElectronConfig = "[Xe] 4f14 5d10 6s2 6p4", DensityUnit = "g/cm3", DiscoveredBy = "Pierre Curie", NamedBy = "", SummaryZh = "钋的放射性极强，是居里夫妇在沥青铀矿里找到的，名字纪念波兰。它主要靠人工生产，用于静电消除器和航天热源；微量就能致命，是顶级危险品。它在早期核实验里当过中子引发剂，如今只剩实验用途。", SummaryEn = "Polonium is ferociously radioactive, found by the Curies in pitchblende and named after Poland. Mostly made artificially for static eliminators and space heat sources, a trace can be lethal, which puts it in the top tier of dangerous goods. It served as a neutron initiator in early nuclear tests, and only experiments remain.", MeltC = 253.9, BoilC = 961.9, Density = 9.2, Electronegativity = 2.0 },
            new ElementDef { Number = 85, Symbol = "At", NameZh = "砹", NameEn = "Astatine", Category = "halogen", Mass = 210.0, Value = 160, Group = 17, Period = 6, Phase = "Solid", Block = "p", ElectronConfig = "[Xe] 4f14 5d10 6s2 6p5", DensityUnit = "g/cm3", DiscoveredBy = "Dale R. Corson", NamedBy = "", SummaryZh = "砹是地壳里最稀有的天然元素，全地球同时存在的量据说不到一勺。它带强放射性，性质像卤素，主要用于靶向放疗研究，基本只存在于实验室。它的半衰期以小时计，刚合成出来就得马上用掉。", SummaryEn = "Astatine is the rarest natural element in the crust, with allegedly less than a spoonful existing on Earth at once. Strongly radioactive and halogen-like, it is mainly studied for targeted radiotherapy and exists only in laboratories. Its half-life is measured in hours, so it must be used the moment it is made.", MeltC = 301.9, BoilC = 336.9, Density = 6.35, Electronegativity = 2.2 },
            new ElementDef { Number = 86, Symbol = "Rn", NameZh = "氡", NameEn = "Radon", Category = "noble_gas", Mass = 222.0, Value = 90, Group = 18, Period = 6, Phase = "Gas", Block = "p", ElectronConfig = "[Xe] 4f14 5d10 6s2 6p6", DensityUnit = "g/L", DiscoveredBy = "Friedrich Ernst Dorn", NamedBy = "", SummaryZh = "氡是铀衰变产生的放射性气体，会从地基和建材里渗进屋子，是肺癌的重要诱因。它无色无味，通风和检测是唯一办法；也曾在放疗中短暂使用过。它比空气重，会沉在地下室和矿井底部等着人。", SummaryEn = "Radon is a radioactive gas born from uranium decay that seeps into homes from soil and building materials, a major cause of lung cancer. It is colorless and odorless, so only ventilation and testing help, and it was briefly used in radiotherapy long ago. Heavier than air, it sinks into basements and mine bottoms to wait.", MeltC = -71.1, BoilC = -61.6, Density = 9.73, Electronegativity = 2.2 },
            new ElementDef { Number = 87, Symbol = "Fr", NameZh = "钫", NameEn = "Francium", Category = "alkali_metal", Mass = 223.0, Value = 200, Group = 1, Period = 7, Phase = "Solid", Block = "s", ElectronConfig = "[Rn] 7s1", DensityUnit = "g/cm3", DiscoveredBy = "Marguerite Perey", NamedBy = "", SummaryZh = "钫是最不稳定的天然元素之一，半衰期短到无法累积，地壳里只有极微量。它从铀的衰变链里冒出来，性质像铯，只能在实验室里瞬间研究，当铺里不可能有现货。它每次只被合成出极少量原子，计量单位是粒子而不是克。", SummaryEn = "Francium is among the most unstable natural elements, its half-life too short to accumulate, leaving only traces in the crust. It bubbles up from the uranium decay chain and behaves like cesium, can only be studied for moments in a lab, and no pawnshop will ever hold stock. Only tiny numbers of its atoms are made at a time, counted in particles, not grams.", MeltC = 26.9, BoilC = 676.9, Density = 1.87, Electronegativity = 0.79 },
            new ElementDef { Number = 88, Symbol = "Ra", NameZh = "镭", NameEn = "Radium", Category = "alkaline_earth", Mass = 226.0, Value = 150, Group = 2, Period = 7, Phase = "Solid", Block = "s", ElectronConfig = "[Rn] 7s2", DensityUnit = "g/cm3", DiscoveredBy = "Pierre Curie", NamedBy = "", SummaryZh = "镭会自己发光，早年做夜光表盘害惨了一整代女工。它和钙一样会沉积在骨骼里，长期照射引发骨癌；如今只用于少量癌症治疗，属高度管制品。它的盐曾被加进化妆品和保健品，那是最黑的一段生意。", SummaryEn = "Radium glows on its own, and early luminous watch dials poisoned a whole generation of women workers. It settles into bone like calcium and causes bone cancer under long exposure, and today it serves only a little cancer therapy under heavy control. Its salts were once added to cosmetics and tonics, the darkest chapter of the trade.", MeltC = 959.9, BoilC = 1736.8, Density = 5.5, Electronegativity = 0.9 },
            new ElementDef { Number = 89, Symbol = "Ac", NameZh = "锕", NameEn = "Actinium", Category = "actinide", Mass = 227.0, Value = 160, Group = 0, Period = 7, Phase = "Solid", Block = "f", ElectronConfig = "[Rn] 6d1 7s2", DensityUnit = "g/cm3", DiscoveredBy = "Friedrich Oskar Giesel", NamedBy = "", SummaryZh = "锕的放射性极强，在暗处会发出淡蓝色的光。它从铀矿里提取，用作中子源和靶向治疗研究；样品极难保存，属于放射源管理里最严的一档。它在地壳里只以痕量存在，想凑一克得处理成吨铀矿。", SummaryEn = "Actinium is intensely radioactive and glows faint blue in the dark. Extracted from uranium ore, it serves as a neutron source and in targeted therapy research, and its samples are extremely hard to keep, placing it in the strictest class of radioactive sources. It exists only in traces, and a gram means processing tons of uranium ore.", MeltC = 1226.8, BoilC = 3226.8, Density = 10.0, Electronegativity = 1.1 },
            new ElementDef { Number = 90, Symbol = "Th", NameZh = "钍", NameEn = "Thorium", Category = "actinide", Mass = 232.04, Value = 80, Group = 0, Period = 7, Phase = "Solid", Block = "f", ElectronConfig = "[Rn] 6d2 7s2", DensityUnit = "g/cm3", DiscoveredBy = "Jöns Jakob Berzelius", NamedBy = "", SummaryZh = "钍在自然界比铀丰富，被看作核能的潜在替代燃料。它也曾用于煤气灯纱罩，放射性温和但长期吸入粉尘有害；钍基熔盐堆是近年研究热点。它的氧化物耐火，实验室坩埚里也曾用过。", SummaryEn = "Thorium is more abundant in nature than uranium and is seen as a potential alternative nuclear fuel. It also served gas-lamp mantles, its radioactivity is mild but long-term dust inhalation is harmful, and thorium molten-salt reactors are a current research favorite. Its oxide is refractory and once lined laboratory crucibles.", MeltC = 1749.8, BoilC = 4787.9, Density = 11.72, Electronegativity = 1.3 },
            new ElementDef { Number = 91, Symbol = "Pa", NameZh = "镤", NameEn = "Protactinium", Category = "actinide", Mass = 231.04, Value = 170, Group = 0, Period = 7, Phase = "Solid", Block = "f", ElectronConfig = "[Rn] 5f2 6d1 7s2", DensityUnit = "g/cm3", DiscoveredBy = "William Crookes", NamedBy = "Otto Hahn", SummaryZh = "镤极稀少又极放射，从铀矿里分离一点点都费尽力气。它曾长期只存在于理论推测中，如今主要用于科研和放射性示踪，普通当铺连见都见不到。它的放射性比镭还难缠，取样和存放都得在密封箱里完成。", SummaryEn = "Protactinium is extremely scarce and extremely radioactive, and separating even a little from uranium ore is exhausting work. It long existed only in theoretical predictions, and today it serves research and radioactive tracers; an ordinary shop will never see it. Its radioactivity is nastier than radium's, and both sampling and storage happen in sealed boxes.", MeltC = 1567.8, BoilC = 4026.8, Density = 15.37, Electronegativity = 1.5 },
            new ElementDef { Number = 92, Symbol = "U", NameZh = "铀", NameEn = "Uranium", Category = "actinide", Mass = 238.03, Value = 200, Group = 0, Period = 7, Phase = "Solid", Block = "f", ElectronConfig = "[Rn] 5f3 6d1 7s2", DensityUnit = "g/cm3", DiscoveredBy = "Martin Heinrich Klaproth", NamedBy = "", SummaryZh = "铀是核裂变燃料的主角，天然铀里能裂变的铀-235 只占很小一部分，需要浓缩。它也给核潜艇和核电站供能，贫铀还能做装甲；放射性和化学毒性都要防。它的衰变链还会生出氡，矿洞通风不好就是慢性的刀子。", SummaryEn = "Uranium is the star fuel of nuclear fission, and natural uranium holds only a small share of fissile uranium-235, so it must be enriched. It powers submarines and reactors, depleted uranium makes armor, and both its radioactivity and its chemical toxicity need guarding. Its decay chain breeds radon, and a poorly ventilated mine is a slow blade.", MeltC = 1132.2, BoilC = 4130.9, Density = 19.1, Electronegativity = 1.38 },
            new ElementDef { Number = 93, Symbol = "Np", NameZh = "镎", NameEn = "Neptunium", Category = "actinide", Mass = 237.0, Value = 220, Group = 0, Period = 7, Phase = "Solid", Block = "f", ElectronConfig = "[Rn] 5f4 6d1 7s2", DensityUnit = "g/cm3", DiscoveredBy = "Edwin McMillan", NamedBy = "", SummaryZh = "镎是第一个被合成出来的超铀元素，名字跟着海王星走。它有强放射性，用于中子探测和中子源，也作为钚生产的中间产物存在，全程受核材料管制。它在地壳里只有痕量，想要样品只能靠反应堆慢慢养。", SummaryEn = "Neptunium was the first transuranic element made by humans, named after the planet Neptune. Strongly radioactive, it serves neutron detection and neutron sources and appears as an intermediate in plutonium production, all under nuclear material controls. The crust holds only traces, so samples must be grown slowly in reactors.", MeltC = 638.9, BoilC = 4173.9, Density = 20.45, Electronegativity = 1.36 },
            new ElementDef { Number = 94, Symbol = "Pu", NameZh = "钚", NameEn = "Plutonium", Category = "actinide", Mass = 244.0, Value = 240, Group = 0, Period = 7, Phase = "Solid", Block = "f", ElectronConfig = "[Rn] 5f6 7s2", DensityUnit = "g/cm3", DiscoveredBy = "Glenn T. Seaborg", NamedBy = "", SummaryZh = "钚是核武器和核反应堆的关键材料，钚-238 还能给深空探测器供电。它放射性强、化学毒性大，处理必须在密封手套箱里，废土上等于天灾。它的临界质量一旦凑够就会自行链式反应，存放按形状算。", SummaryEn = "Plutonium is the key material of nuclear weapons and reactors, and plutonium-238 even powers deep-space probes. Its radioactivity and chemical toxicity are severe, handling demands sealed gloveboxes, and in the wasteland it amounts to a disaster. Once enough gathers, it chain-reacts on its own, so storage is calculated by shape.", MeltC = 639.4, BoilC = 3231.8, Density = 19.82, Electronegativity = 1.28 },
            new ElementDef { Number = 95, Symbol = "Am", NameZh = "镅", NameEn = "Americium", Category = "actinide", Mass = 243.0, Value = 250, Group = 0, Period = 7, Phase = "Solid", Block = "f", ElectronConfig = "[Rn] 5f7 7s2", DensityUnit = "g/cm3", DiscoveredBy = "Glenn T. Seaborg", NamedBy = "", SummaryZh = "镅是人工合成的超铀元素，离子式烟雾报警器里那一小片就是它。它放射 α 粒子，量少但持续，属于受控放射源；废土上拆烟雾器可是要命的手艺。它的氧化物能做出便携中子源，探矿队曾靠它找矿。", SummaryEn = "Americium is a synthetic transuranic element, and the tiny speck in an ionizing smoke detector is it. It emits alpha particles constantly even in small amounts, making it a controlled radioactive source, and stripping smoke detectors in the wasteland is a deadly trade. Its oxide makes portable neutron sources, and prospecting crews once hunted ore with it.", MeltC = 1175.8, BoilC = 2606.8, Density = 12.0, Electronegativity = 1.13 },
            new ElementDef { Number = 96, Symbol = "Cm", NameZh = "锔", NameEn = "Curium", Category = "actinide", Mass = 247.0, Value = 255, Group = 0, Period = 7, Phase = "Solid", Block = "f", ElectronConfig = "[Rn] 5f7 6d1 7s2", DensityUnit = "g/cm3", DiscoveredBy = "Glenn T. Seaborg", NamedBy = "", SummaryZh = "锔以居里夫妇命名，是人工合成的强放射性元素。它曾给火星车的 α 粒子光谱仪当放射源，也用于空间电源研究；只能靠反应堆辐照少量生产。它的放射性强到会自己把样品烧热，容器得用特殊合金。", SummaryEn = "Curium is named for the Curies and is a synthetic, intensely radioactive element. It once supplied the alpha particle source for a Mars rover's spectrometer and serves space power research, and only reactors can irradiate the small amounts that exist. It is radioactive enough to heat its own sample, and containers need special alloys.", MeltC = 1339.8, BoilC = 3109.8, Density = 13.51, Electronegativity = 1.28 },
            new ElementDef { Number = 97, Symbol = "Bk", NameZh = "锫", NameEn = "Berkelium", Category = "actinide", Mass = 247.0, Value = 258, Group = 0, Period = 7, Phase = "Solid", Block = "f", ElectronConfig = "[Rn] 5f9 7s2", DensityUnit = "g/cm3", DiscoveredBy = "Lawrence Berkeley National Laboratory", NamedBy = "", SummaryZh = "锫以美国伯克利命名，是人工合成的超铀元素，产量以微克计。它主要用于合成更重元素的靶材和基础研究，半衰期短，现实中没有任何日常用途。它在地壳里根本不存在，只能靠反应堆一点点攒出来。", SummaryEn = "Berkelium is named after Berkeley, California, and is a synthetic transuranic element made atom by atom. It mainly serves as a target for making heavier elements and for basic research, its half-life is short, and it has no everyday use. It does not exist in the crust at all, so it can only be accumulated slowly in a reactor.", MeltC = 985.9, BoilC = 2626.8, Density = 14.78, Electronegativity = 1.3 },
            new ElementDef { Number = 98, Symbol = "Cf", NameZh = "锎", NameEn = "Californium", Category = "actinide", Mass = 251.0, Value = 260, Group = 0, Period = 7, Phase = "Solid", Block = "f", ElectronConfig = "[Rn] 5f10 7s2", DensityUnit = "g/cm3", DiscoveredBy = "Lawrence Berkeley National Laboratory", NamedBy = "", SummaryZh = "锎是能当强中子源用的超铀元素，石油测井和癌症治疗都有它的身影。它靠反应堆长期辐照生产，价格以微克计，属最贵的物质之一，全程严格管控。它自发裂变放出的中子密得像雨，探矿仪里塞一点就够用。", SummaryEn = "Californium is a transuranic element strong enough to serve as a neutron source, used in oil well logging and cancer therapy. Reactors irradiate it for a long time to make micrograms, it is among the most expensive substances, and it is strictly controlled. Its spontaneous fission sprays neutrons like rain, and a speck is enough for a prospecting instrument.", MeltC = 899.9, BoilC = 1469.8, Density = 15.1, Electronegativity = 1.3 },
            new ElementDef { Number = 99, Symbol = "Es", NameZh = "锿", NameEn = "Einsteinium", Category = "actinide", Mass = 252.0, Value = 240, Group = 0, Period = 7, Phase = "Solid", Block = "f", ElectronConfig = "[Rn] 5f11 7s2", DensityUnit = "g/cm3", DiscoveredBy = "Lawrence Berkeley National Laboratory", NamedBy = "", SummaryZh = "锿以爱因斯坦命名，最早是在氢弹试验残骸里被找到的。它放射性强、产量极微，主要用于合成更重元素和研究，普通人一辈子都接触不到。它在元素周期表上留下名字，现实里却没有一克存货。", SummaryEn = "Einsteinium is named for Einstein and was first found in the debris of a hydrogen bomb test. Intensely radioactive and produced in vanishingly small amounts, it mainly serves to synthesize heavier elements and for research, out of reach for ordinary people. It left a name on the periodic table and not a gram in reality.", MeltC = 859.9, BoilC = 995.9, Density = 8.84, Electronegativity = 1.3 },
            new ElementDef { Number = 100, Symbol = "Fm", NameZh = "镄", NameEn = "Fermium", Category = "actinide", Mass = 257.0, Value = 235, Group = 0, Period = 7, Phase = "Solid", Block = "f", ElectronConfig = "[Rn] 5f12 7s2", DensityUnit = "g/cm3", DiscoveredBy = "Lawrence Berkeley National Laboratory", NamedBy = "", SummaryZh = "镄以费米命名，同样是人工合成的超铀元素。它只能在加速器和反应堆里按原子造出来，用于基础核化学研究，半衰期短得无法称量，更谈不上应用。它的发现靠的是分析核爆尘埃里的衰变链，照片都没有一张。", SummaryEn = "Fermium is named for Fermi and is likewise synthetic. It can only be made atom by atom in accelerators and reactors for basic nuclear chemistry, its half-life is too short to weigh, let alone use. It was discovered by reading decay chains in bomb debris, without a single photograph.", MeltC = 1526.8, Electronegativity = 1.3 },
            new ElementDef { Number = 101, Symbol = "Md", NameZh = "钔", NameEn = "Mendelevium", Category = "actinide", Mass = 258.0, Value = 230, Group = 0, Period = 7, Phase = "Solid", Block = "f", ElectronConfig = "[Rn] 5f13 7s2", DensityUnit = "g/cm3", DiscoveredBy = "Lawrence Berkeley National Laboratory", NamedBy = "", SummaryZh = "钔以门捷列夫命名，是第一种只能一个原子一个原子研究的元素。它放射性强、寿命短，用于研究锕系元素的化学行为，现实中没有任何库存可言。它的化学性质只能靠几十个原子的实验去猜，误差大得惊人。", SummaryEn = "Mendelevium is named for Mendeleev and was the first element studied one atom at a time. Strongly radioactive and short-lived, it serves research on actinide chemistry, and no real inventory of it exists. Its chemistry is guessed from experiments on dozens of atoms, with startling error bars.", MeltC = 826.9, Electronegativity = 1.3 },
            new ElementDef { Number = 102, Symbol = "No", NameZh = "锘", NameEn = "Nobelium", Category = "actinide", Mass = 259.0, Value = 225, Group = 0, Period = 7, Phase = "Solid", Block = "f", ElectronConfig = "[Rn] 5f14 7s2", DensityUnit = "g/cm3", DiscoveredBy = "Joint Institute for Nuclear Research", NamedBy = "", SummaryZh = "锘以诺贝尔命名，人工合成、放射性极强。它的发现史有过争议，如今只在实验室里按原子研究；所谓用途基本是科研和教学，废土上纯属传说。它的寿命以分钟计，合成出来还没装瓶就衰变掉大半。", SummaryEn = "Nobelium is named for Nobel, synthetic and intensely radioactive. Its discovery history was disputed, and today it is studied atom by atom in labs; its uses are basically research and teaching, a pure legend in the wasteland. Its life is measured in minutes, and most of it decays before it can be bottled.", MeltC = 826.9, Electronegativity = 1.3 },
            new ElementDef { Number = 103, Symbol = "Lr", NameZh = "铹", NameEn = "Lawrencium", Category = "actinide", Mass = 266.0, Value = 220, Group = 0, Period = 7, Phase = "Solid", Block = "d", ElectronConfig = "[Rn] 5f14 7s2 7p1", DensityUnit = "g/cm3", DiscoveredBy = "Lawrence Berkeley National Laboratory", NamedBy = "", SummaryZh = "铹以劳伦斯命名，是锕系最后一个成员，也是人工合成的短命元素。它只在加速器里出现，用于检验周期表理论，半衰期短到刚造出来就衰变。它的化学性质至今靠同族元素外推，没人亲眼见过。", SummaryEn = "Lawrencium is named for Lawrence and is the last member of the actinides, synthetic and short-lived. It appears only in accelerators to test periodic-table theory, decaying almost as soon as it is made. Its chemistry is still extrapolated from its neighbors; no one has seen it directly.", MeltC = 1626.8, Electronegativity = 1.3 },
            new ElementDef { Number = 104, Symbol = "Rf", NameZh = "𬬻", NameEn = "Rutherfordium", Category = "transition_metal", Mass = 267.0, Value = 210, Group = 4, Period = 7, Phase = "Solid", Block = "d", ElectronConfig = "[Rn] 5f14 6d2 7s2", DensityUnit = "g/cm3", DiscoveredBy = "Joint Institute for Nuclear Research", NamedBy = "", SummaryZh = "𬬻以卢瑟福命名，是第一个超锕系元素，只能靠重离子碰撞一个个造出来。它的化学性质据推测类似铪，研究一次要用掉大量机时，现实中没有库存。它没有价格，因为没人卖得出一克。", SummaryEn = "Rutherfordium is named for Rutherford and is the first transactinide, built one atom at a time by heavy-ion collisions. Its chemistry is thought to resemble hafnium's, a single study consumes enormous machine time, and no stock exists in reality. It has no price, because no one can sell a gram of it.", MeltC = 2126.8, BoilC = 5526.9, Density = 23.2 },
            new ElementDef { Number = 105, Symbol = "Db", NameZh = "𬭊", NameEn = "Dubnium", Category = "transition_metal", Mass = 268.0, Value = 205, Group = 5, Period = 7, Phase = "Solid", Block = "d", ElectronConfig = "*[Rn] 5f14 6d3 7s2", DensityUnit = "g/cm3", DiscoveredBy = "Joint Institute for Nuclear Research", NamedBy = "", SummaryZh = "𬭊以俄罗斯杜布纳命名，是冷战时期美苏争相合成的超重元素之一。它寿命极短，只能通过衰变链识别，化学实验要用单原子方法做，谈不上实际用途。它和钽、铌同族，理论上该像它们一样耐蚀。", SummaryEn = "Dubnium is named for Dubna, Russia, one of the superheavy elements the Cold War rivals raced to synthesize. Its life is extremely short and it can only be identified through decay chains, with chemistry done one atom at a time, so practical use is nil. It shares a group with tantalum and niobium and should be equally corrosion-proof in theory.", Density = 29.3 },
            new ElementDef { Number = 106, Symbol = "Sg", NameZh = "𬭳", NameEn = "Seaborgium", Category = "transition_metal", Mass = 269.0, Value = 200, Group = 6, Period = 7, Phase = "Solid", Block = "d", ElectronConfig = "*[Rn] 5f14 6d4 7s2", DensityUnit = "g/cm3", DiscoveredBy = "Lawrence Berkeley National Laboratory", NamedBy = "", SummaryZh = "𬭳以西博格命名，是少数在命名时就还活着的科学家冠名的元素。它只能原子级合成，科学家用单原子色谱研究它的化学性质，现实中完全是实验室产物。它在废土上没有买家，只在实验室的靶室里有户口。", SummaryEn = "Seaborgium is named for Seaborg, one of the few elements named after a living scientist. It can only be synthesized atom by atom, and researchers use single-atom chromatography to probe its chemistry; it is purely a laboratory product. No buyers in the wasteland; it is registered only in a lab's target chamber.", Density = 35.0 },
            new ElementDef { Number = 107, Symbol = "Bh", NameZh = "𬭛", NameEn = "Bohrium", Category = "transition_metal", Mass = 270.0, Value = 195, Group = 7, Period = 7, Phase = "Solid", Block = "d", ElectronConfig = "*[Rn] 5f14 6d5 7s2", DensityUnit = "g/cm3", DiscoveredBy = "Gesellschaft für Schwerionenforschung", NamedBy = "", SummaryZh = "𬭛以玻尔命名，是德国重离子研究所合成的超重元素。它每次只生成几个原子，半衰期以秒计，仅用于验证核结构和周期表规律，没有商业价值。它的名字排在玻尔之后，实验数据却薄得可怜。", SummaryEn = "Bohrium is named for Bohr and was synthesized at Germany's heavy-ion institute. Only a few atoms form at a time and its half-life is measured in seconds, so it serves only to verify nuclear structure and periodic trends, with no commercial value. It carries Bohr's name, yet the data on it is pitifully thin.", Density = 37.1 },
            new ElementDef { Number = 108, Symbol = "Hs", NameZh = "𬭶", NameEn = "Hassium", Category = "transition_metal", Mass = 269.0, Value = 190, Group = 8, Period = 7, Phase = "Solid", Block = "d", ElectronConfig = "*[Rn] 5f14 6d6 7s2", DensityUnit = "g/cm3", DiscoveredBy = "Gesellschaft für Schwerionenforschung", NamedBy = "", SummaryZh = "𬭶以德国黑森州命名，是重离子研究所的招牌成果之一。它的原子数少到要逐个计数，化学性质研究极为困难，只存在于加速器靶室的瞬间。它的化学实验要用气流把单个原子带走，再逐个检测。", SummaryEn = "Hassium is named for the German state of Hesse and is a signature result of the heavy-ion institute. Its atoms are so few that they must be counted one by one, making chemical study extremely hard, and it exists only for an instant in a target chamber. Its chemistry needs a gas stream to carry single atoms away for one-by-one detection.", Density = 40.7 },
            new ElementDef { Number = 109, Symbol = "Mt", NameZh = "鿏", NameEn = "Meitnerium", Category = "transition_metal", Mass = 278.0, Value = 185, Group = 9, Period = 7, Phase = "Solid", Block = "d", ElectronConfig = "*[Rn] 5f14 6d7 7s2", DensityUnit = "g/cm3", DiscoveredBy = "Gesellschaft für Schwerionenforschung", NamedBy = "", SummaryZh = "鿏以迈特纳命名，是人工合成的超重元素，从未以可见量存在过。它通过重离子熔合产生，寿命短到秒级，只用于核物理研究，当铺里连样品都摆不出。它一次只生成一个原子，连化学性质都还没摸清。", SummaryEn = "Meitnerium is named for Meitner and is a synthetic superheavy element that has never existed in visible quantity. Made by heavy-ion fusion with a half-life of seconds, it serves nuclear physics research only, and no sample can be put on a shelf. One atom at a time is created, and its chemistry is still barely touched.", Density = 37.4 },
            new ElementDef { Number = 110, Symbol = "Ds", NameZh = "𫟼", NameEn = "Darmstadtium", Category = "transition_metal", Mass = 281.0, Value = 180, Group = 10, Period = 7, Phase = "Solid", Block = "d", ElectronConfig = "*[Rn] 5f14 6d9 7s1", DensityUnit = "g/cm3", DiscoveredBy = "Gesellschaft für Schwerionenforschung", NamedBy = "", SummaryZh = "𫟼以德国达姆施塔特命名，是重离子研究所合成的超重元素。它一次只生成几个原子，迅速衰变成更轻的元素，研究价值在核结构而不在任何实际用途。它的名字来自实验室所在的城市，实验数据只有几行。", SummaryEn = "Darmstadtium is named for Darmstadt, Germany, and was synthesized at the heavy-ion institute. Only a few atoms form at a time and decay quickly into lighter elements, so its value lies in nuclear structure rather than any application. Named after the city of its lab, it has only a few lines of data to its name.", Density = 34.8 },
            new ElementDef { Number = 111, Symbol = "Rg", NameZh = "𬬭", NameEn = "Roentgenium", Category = "transition_metal", Mass = 282.0, Value = 175, Group = 11, Period = 7, Phase = "Solid", Block = "d", ElectronConfig = "*[Rn] 5f14 6d10 7s1", DensityUnit = "g/cm3", DiscoveredBy = "Gesellschaft für Schwerionenforschung", NamedBy = "", SummaryZh = "𬬭以伦琴命名，理论上是铜那一列的超重亲戚，可能呈现类似贵金属的性质。它只能原子级合成，半衰期极短，现实中无法收集，纯属周期表上的展品。它连可见量都凑不出，只能在论文的表格里占一格。", SummaryEn = "Roentgenium is named for Röntgen and is theoretically a superheavy cousin of copper, possibly with precious-metal behavior. It can only be made atom by atom with an extremely short half-life, so nothing can be collected; it is a display piece on the periodic table. Not even a visible amount exists, and it occupies one cell in a paper's table.", Density = 28.7 },
            new ElementDef { Number = 112, Symbol = "Cn", NameZh = "鿔", NameEn = "Copernicium", Category = "transition_metal", Mass = 285.0, Value = 170, Group = 12, Period = 7, Phase = "Liquid", Block = "d", ElectronConfig = "*[Rn] 5f14 6d10 7s2", DensityUnit = "g/cm3", DiscoveredBy = "Gesellschaft für Schwerionenforschung", NamedBy = "", SummaryZh = "鿔以哥白尼命名，理论预测它的性质更像挥发的液态金属，而非汞的翻版。它靠铅靶轰击锌束合成，一次几个原子，是检验相对论效应的热门研究对象。它的名字给了一位天文学家，样品却比星光还难留。", SummaryEn = "Copernicium is named for Copernicus, and theory predicts a volatile, liquid-like metal rather than a copy of mercury. Made by firing zinc at lead, a few atoms at a time, it is a favorite test case for relativistic effects. Its name went to an astronomer, and its samples are harder to keep than starlight.", MeltC = 9.9, BoilC = 66.9, Density = 14.0 },
            new ElementDef { Number = 113, Symbol = "Nh", NameZh = "鿭", NameEn = "Nihonium", Category = "post_transition", Mass = 286.0, Value = 165, Group = 13, Period = 7, Phase = "Solid", Block = "p", ElectronConfig = "*[Rn] 5f14 6d10 7s2 7p1", DensityUnit = "g/cm3", DiscoveredBy = "RIKEN", NamedBy = "", SummaryZh = "鿭以日本命名，是亚洲国家命名的第一个元素。它由理化学研究所用重离子碰撞合成，产量按原子计，半衰期短，只用于核物理研究，没有实际库存。它的发现让日本在元素版图上有了第一块地盘。", SummaryEn = "Nihonium is named for Japan and is the first element named by an Asian country. Synthesized at RIKEN by heavy-ion collisions, it comes out by the atom, has a short half-life, and serves nuclear physics only, with no practical stock. Its discovery gave Japan its first foothold on the element map.", MeltC = 426.9, BoilC = 1156.8, Density = 16.0 },
            new ElementDef { Number = 114, Symbol = "Fl", NameZh = "𫓧", NameEn = "Flerovium", Category = "post_transition", Mass = 289.0, Value = 160, Group = 14, Period = 7, Phase = "Solid", Block = "p", ElectronConfig = "*[Rn] 5f14 6d10 7s2 7p2", DensityUnit = "g/cm3", DiscoveredBy = "Joint Institute for Nuclear Research", NamedBy = "", SummaryZh = "𫓧以俄罗斯核物理学家弗廖罗夫命名，理论预测它可能像挥发性金属。它由钙束轰击钚靶合成，一次几个原子，属于检验周期表边界的实验品。它附近的元素据说可能靠近稳定岛，实验组一直盯着。", SummaryEn = "Flerovium is named for the Russian nuclear physicist Flerov, and theory predicts a volatile metal. Made by firing calcium at plutonium and produced a few atoms at a time, it is an experiment for testing the edge of the periodic table. The elements near it may approach the island of stability, and labs keep watching.", MeltC = 66.9, BoilC = 146.9, Density = 14.0 },
            new ElementDef { Number = 115, Symbol = "Mc", NameZh = "镆", NameEn = "Moscovium", Category = "post_transition", Mass = 290.0, Value = 155, Group = 15, Period = 7, Phase = "Solid", Block = "p", ElectronConfig = "*[Rn] 5f14 6d10 7s2 7p3", DensityUnit = "g/cm3", DiscoveredBy = "Joint Institute for Nuclear Research", NamedBy = "", SummaryZh = "镆以莫斯科命名，是俄美合作合成的超重元素。它只能靠重离子熔合产生，半衰期极短，用于研究超重核的稳定岛假说，现实中没有任何用途。它的合成需要几个月的束流时间，换来几个原子。", SummaryEn = "Moscovium is named for Moscow and is a superheavy element synthesized by Russian and American collaboration. It can only be made by heavy-ion fusion, decays almost instantly, and tests the island-of-stability idea with no practical use. Months of beam time buy a handful of its atoms.", MeltC = 396.9, BoilC = 1126.8, Density = 13.5 },
            new ElementDef { Number = 116, Symbol = "Lv", NameZh = "𫟷", NameEn = "Livermorium", Category = "post_transition", Mass = 293.0, Value = 150, Group = 16, Period = 7, Phase = "Solid", Block = "p", ElectronConfig = "*[Rn] 5f14 6d10 7s2 7p4", DensityUnit = "g/cm3", DiscoveredBy = "Joint Institute for Nuclear Research", NamedBy = "", SummaryZh = "𫟷以美国利弗莫尔实验室命名，是人工合成的超重元素。它每次只生成少量原子，迅速衰变，研究重点是核稳定性和周期表延伸，商业价值为零。它由钙束轰击锔靶得到，名字归了加州那座实验室。", SummaryEn = "Livermorium is named for the Livermore laboratory in the United States and is synthetic. Only a few atoms form at a time and decay quickly, and research focuses on nuclear stability and extending the periodic table, with zero commercial value. Made by firing calcium at curium, its name went to the California lab.", MeltC = 435.9, BoilC = 811.9, Density = 12.9 },
            new ElementDef { Number = 117, Symbol = "Ts", NameZh = "鿬", NameEn = "Tennessine", Category = "halogen", Mass = 294.0, Value = 145, Group = 17, Period = 7, Phase = "Solid", Block = "p", ElectronConfig = "*[Rn] 5f14 6d10 7s2 7p5", DensityUnit = "g/cm3", DiscoveredBy = "Joint Institute for Nuclear Research", NamedBy = "", SummaryZh = "鿬以美国田纳西州命名，是卤素一列的超重成员，理论性质却更像金属。它由锫靶和钙束反应合成，产量按原子计，只在实验室里存在过很短时间。它的性质至今靠计算推测，卤素的名分还挂着问号。", SummaryEn = "Tennessine is named for the US state of Tennessee and is the superheavy member of the halogens, though theory says it behaves more like a metal. Made from berkelium and calcium, it exists by the atom and only for a short time in a lab. Its properties are still inferred by calculation, and its halogen title remains a question mark.", MeltC = 449.9, BoilC = 609.9, Density = 7.17 },
            new ElementDef { Number = 118, Symbol = "Og", NameZh = "鿫", NameEn = "Oganesson", Category = "noble_gas", Mass = 294.0, Value = 140, Group = 18, Period = 7, Phase = "Solid", Block = "p", ElectronConfig = "*[Rn] 5f14 6d10 7s2 7p6", DensityUnit = "g/cm3", DiscoveredBy = "Joint Institute for Nuclear Research", NamedBy = "", SummaryZh = "鿫以俄罗斯核物理学家奥加涅相命名，是目前已知最重的元素。理论预测它可能不是气体而是固体，靠锎靶和钙束合成，一次一两个原子，纯属科学标本。它的原子核寿命以毫秒计，合成后只够记下衰变产物。", SummaryEn = "Oganesson is named for the Russian nuclear physicist Oganessian and is the heaviest element known. Theory predicts it may be a solid rather than a gas, and it is made from californium and calcium a couple of atoms at a time, a pure scientific specimen. Its nucleus lives for milliseconds, long enough only to log the decay products.", BoilC = 76.9, Density = 4.95 },
        };
    }
}
